
const KEY='dogleg.v7';
const icons={Home:'<path d="m3 9 7-6 7 6v9H3zM8 18v-6h4v6"/>',Rounds:'<rect x="4" y="3" width="12" height="15" rx="2"/><path d="M7 7h6M7 11h6M7 15h3"/>',Passport:'<rect x="3" y="3" width="14" height="15" rx="2"/><circle cx="10" cy="10" r="4"/><path d="M6 10h8M10 6v8"/>',Friends:'<circle cx="7" cy="7" r="3"/><path d="M1 18v-2a6 6 0 0 1 12 0v2M14 4a3 3 0 0 1 0 6M15 12a5 5 0 0 1 4 5"/>',Profile:'<circle cx="10" cy="6" r="3"/><path d="M3 18v-2a7 7 0 0 1 14 0v2"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 20 21" aria-hidden="true">${icons[n]}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');
const initial=()=>({profile:{name:'James',home:'Your home course',goal:20},rounds:[],notes:[],friends:[{id:'f1',name:'Alex Morgan',hcp:12.4,score:84},{id:'f2',name:'Sam Taylor',hcp:16.8,score:89},{id:'f3',name:'Jordan Lee',hcp:9.2,score:79}],challenges:[],shared:[],invites:[],draft:null});
let state=initial(),storageOK=true;try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved)state={...state,...saved}}catch(e){storageOK=false}
let tab='Home',filter='',year=String(new Date().getFullYear());
const main=document.querySelector('#main'),modal=document.querySelector('#modal');
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){storageOK=false;toast('Storage unavailable. Export a backup before closing.');return false}}
function toast(s){document.querySelector('#toast').textContent=s;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>document.querySelector('#toast').textContent='',4000)}
function go(t){tab=t;render();window.scrollTo(0,0)}
function ordered(){return [...state.rounds].sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))}
function differential(r){return Number.isFinite(r.score)&&!r.scoreNotKept&&r.holes===18&&Number.isFinite(r.rating)&&r.rating>=20&&r.rating<=90&&Number.isFinite(r.slope)&&r.slope>=55&&r.slope<=155?(r.score-r.rating)*113/r.slope:null}
function estimate(rs=ordered()){let d=rs.filter(r=>differential(r)!==null).slice(-20).map(differential).sort((a,b)=>a-b);if(d.length<3)return null;return d.slice(0,Math.max(1,Math.floor(d.length*.4))).reduce((a,b)=>a+b,0)/Math.max(1,Math.floor(d.length*.4))}
function fmt(n){return n===null||!Number.isFinite(n)?'—':n.toFixed(1)}
function stats(){let rs=state.rounds,full=rs.filter(r=>r.holes===18&&Number.isFinite(r.score));return `<div class="stats"><div class="stat"><div class="eyebrow">Rounds played</div><strong>${rs.length}</strong><span>Rounds in the books</span></div><div class="stat"><div class="eyebrow">Scoring average</div><strong>${fmt(full.length?full.reduce((a,r)=>a+r.score,0)/full.length:null)}</strong><span>18-hole rounds</span></div><div class="stat"><div class="eyebrow">Handicap estimate</div><strong>${fmt(estimate())}</strong><span>Practice estimate · unofficial</span></div><div class="stat"><div class="eyebrow">Courses explored</div><strong>${new Set(rs.map(r=>r.course.toLowerCase())).size}</strong><span>Places in your Yardage Book</span></div></div>`}
function roundRows(rs){return rs.length?rs.map(r=>`<div class="row"><div class="round-icon">${courseBadge(r)}</div><div class="grow"><strong>${esc(r.course)}</strong><small>${esc(r.date)} · ${r.holes} holes${r.tees?' · '+esc(r.tees)+' tees':''}${r.sample?' · Sample':''}${r.photos?.length?' · '+r.photos.length+(r.photos.length===1?' photo':' photos'):''}</small></div><div class="score ${r.score===null?'is-unscored':''}">${r.score??'Score not kept'}</div><button class="secondary small" onclick="roundForm('${r.id}')" aria-label="View or edit ${esc(r.course)} round">View</button></div>`).join(''):'<div class="empty">Your first round starts the story.<br><button class="text" onclick="roundForm()">Log your first round →</button></div>'}
function trend(records=state.rounds){let rs=[...records].sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id)).filter(r=>differential(r)!==null),pts=rs.map((r,i)=>estimate(rs.slice(0,i+1))).filter(x=>x!==null);if(!pts.length)return '<p class="muted section-gap">Add course rating and slope to three 18-hole rounds to see your trend.</p>';let lo=Math.min(...pts)-2,hi=Math.max(...pts)+2,xy=pts.map((v,i)=>`${15+i*270/Math.max(1,pts.length-1)},${95-(v-lo)/(hi-lo)*75}`);return `<svg class="chart" viewBox="0 0 300 115" preserveAspectRatio="none" role="img" aria-label="Handicap estimate trend, latest ${fmt(pts.at(-1))}"><path d="M15 95H285M15 55H285M15 20H285" stroke="#e8e5db"/><polyline points="${xy.join(' ')}" fill="none" stroke="#425f4b" stroke-width="2.5" vector-effect="non-scaling-stroke"/>${xy.map(p=>`<path d="M${p}h0" stroke="#425f4b" stroke-width="6" stroke-linecap="round" vector-effect="non-scaling-stroke"/>`).join('')}</svg><div class="legend"><span>First estimate</span><span>Latest · ${fmt(pts.at(-1))}</span></div>`}
function heading(k,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`}
function render(){document.querySelector('nav').innerHTML=navigationItems();document.querySelector('.avatar').textContent=state.profile.name.charAt(0).toUpperCase();main.innerHTML=profileSections()+views[tab]()+`<footer class="footer"><span>DOGLEG &nbsp; / &nbsp; A life well played.</span><span>V7 · Saved on this device${storageOK?'':' · Storage unavailable'}</span></footer>`}

function honoursBoard(){const players=[...state.friends.map(f=>({name:f.name,score:f.score})),...(state.rounds.some(r=>r.holes===18&&Number.isFinite(r.score))?[{name:state.profile.name+' (you)',score:Math.min(...state.rounds.filter(r=>r.holes===18&&Number.isFinite(r.score)).map(r=>r.score))}]:[])].sort((a,b)=>a.score-b.score);return `<section class="honours-board" aria-label="Club honours leaderboard"><div class="board-kicker">THE DOGLEG CLUB</div><h2>The Honours Board</h2><p class="board-subtitle">A friendly contest, a fine tradition.</p><div class="board-columns"><span>Member</span><span>Strokes</span></div>${players.map((f,i)=>`<div class="row"><span class="eyebrow">0${i+1}</span><strong class="grow">${esc(f.name)}</strong><span class="score">${f.score}</span></div>`).join('')}<div class="board-foot">LOCAL DEMO · BEST GROSS · 18 HOLES</div></section>`}

const views={
Home:()=>`<div class="intro"><div class="eyebrow">Your locker is right where you left it</div><h1>Welcome back, ${esc(state.profile.name)}.</h1><p class="muted">Come on in. Set your bag down. Stay a while.</p></div><section class="hero"><div><div class="eyebrow">There's always another round</div><h2>Another round.<br>Another good story.</h2><p>A familiar fairway. A few good friends.<br>There’s no place quite like the club.</p><button onclick="roundForm()">${state.draft?'Resume your round':'＋ Log a round'}</button></div><span class="hero-tag">YOUR VIEW. YOUR JOURNEY.</span></section>${stats()}<div class="grid"><section class="card"><div class="card-head"><h2>Recent rounds</h2><button class="text small" onclick="go('Rounds')">All rounds ↗</button></div>${roundRows(ordered().reverse().slice(0,3))}</section><section class="card"><div class="card-head"><h2>Your game, lately</h2><span class="badge">The numbers</span></div><p class="muted" style="font-size:12px">Handicap estimate over time</p>${trend()}<button class="text small section-gap" onclick="go('Rounds')">Explore your statistics →</button></section></div><div class="section-gap">${honoursBoard()}</div><section class="card section-gap"><div class="card-head"><div><div class="eyebrow">Around the clubhouse</div><h2 style="margin-top:6px">Golf with friends.</h2></div><button class="secondary" onclick="go('Friends')">Your clubhouse →</button></div><p class="muted">Try shared rounds, friendly challenges, and a little healthy competition. <span class="badge demo">Local demo</span></p></section>`,
Rounds:()=>`${heading('On the scorecard','Your rounds.','Log a round. Find your patterns. Enjoy the progress.','<button onclick="roundForm()">＋ Log a round</button>')}${stats()}<div class="grid"><section class="card"><div class="card-head"><h2>Your rounds</h2><span class="badge">${state.rounds.length} saved</span></div><label>Find a course<input id="round-search" placeholder="Search your rounds" value="${esc(filter)}" oninput="filter=this.value;document.querySelector('#round-list').innerHTML=roundRows(ordered().reverse().filter(r=>r.course.toLowerCase().includes(filter.toLowerCase())))"></label><div id="round-list">${roundRows(ordered().reverse().filter(r=>r.course.toLowerCase().includes(filter.toLowerCase())))}</div></section><section class="card"><h2>Handicap trend</h2>${trend()}<p class="muted section-gap" style="font-size:12px">This practice estimate uses the lowest 40% of score differentials from your latest 20 eligible 18-hole rounds (minimum 3). It is not a WHS Handicap Index. Nine-hole rounds are saved separately and excluded.</p><div class="mini-metrics"><div><strong>${state.rounds.filter(r=>r.holes===18&&Number.isFinite(r.score)).length?Math.min(...state.rounds.filter(r=>r.holes===18&&Number.isFinite(r.score)).map(r=>r.score)):'—'}</strong><small>Best 18-hole score</small></div><div><strong>${fmt(state.rounds.some(r=>r.putts!==null)?state.rounds.filter(r=>r.putts!==null).reduce((s,r)=>s+r.putts,0)/state.rounds.filter(r=>r.putts!==null).length:null)}</strong><small>Putts / round</small></div></div></section></div>`,
Passport:()=>{let courses=[...new Map(ordered().map(r=>[r.course.toLowerCase(),r])).values()],notes=state.notes.filter(n=>n.date.startsWith(year));return `${heading('Collect memories','Your course passport.','Different fairways. Stories worth keeping.')}<div class="stamp-grid">${courses.length?courses.map((r,i)=>`<article class="stamp"><div class="stamp-symbol">${String(i+1).padStart(2,'0')}</div><div class="eyebrow">Played · ${esc(r.date)}</div><h3 style="margin-top:10px">${esc(r.course)}</h3><p>${state.rounds.filter(x=>x.course.toLowerCase()===r.course.toLowerCase()).length} visits · Latest score ${r.score??'Score not kept'}</p><span class="badge">Passport stamped</span></article>`).join(''):'<div class="card full"><h2>Your next course is your first stamp.</h2><p class="muted section-gap">Courses appear here automatically when you save a round.</p><button class="text section-gap" onclick="roundForm()">Start your passport →</button></div>'}</div><section class="card section-gap"><div class="card-head"><div><div class="eyebrow">Beyond the score</div><h2 style="margin-top:7px">The yearbook</h2></div><button class="secondary" onclick="noteForm()">＋ Add a memory</button></div><label style="max-width:160px">Year<select onchange="year=this.value;render()">${[...new Set([String(new Date().getFullYear()),...state.notes.map(n=>n.date.slice(0,4)),...state.rounds.map(r=>r.date.slice(0,4))])].sort().reverse().map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><p class="muted">${state.rounds.filter(r=>r.date.startsWith(year)).length} rounds · ${notes.length} memories in ${year}</p>${notes.length?notes.map(n=>`<article class="year-note"><small class="eyebrow">${esc(n.date)}</small><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><button class="text small" onclick="noteForm('${n.id}')">Edit memory</button></article>`).join(''):'<p class="empty">The perfect putt. The people you played with.<br>Save the details you don’t want to forget.</p>'}<button class="text" onclick="window.print()">Print this yearbook ↗</button></section>`},
Friends:()=>`${heading('The clubhouse','Your clubhouse.','Your people, on and off the course.','<button onclick="inviteForm()">＋ Invite</button>')}<div class="notice"><strong>Local Friends demo</strong> · Fictional people and results. Plans and challenges are practice entries in your journal. No invitations or messages are sent.</div><div class="friend-grid"><div><section class="card"><div class="card-head"><h2>Your foursome</h2><span class="badge demo">${state.friends.length} demo friends</span></div>${state.friends.map(f=>`<div class="row"><div class="avatar">${esc(f.name.split(' ').map(x=>x[0]).join(''))}</div><div class="grow"><strong>${esc(f.name)}</strong><small>Demo handicap · ${f.hcp}</small></div><button class="secondary small" onclick="sharedForm('${f.id}')">Plan round</button></div>`).join('')}<div class="friend-actions"><button class="text" onclick="inviteForm()">Invite someone new →</button></div></section><section class="card section-gap"><div class="card-head"><h2>Recent activity</h2><span class="badge demo">Demo</span></div>${[...state.shared].reverse().map(s=>`<div class="row"><span class="activity-dot"></span><div><strong>Round planned with ${esc(s.friend)}</strong><small>${esc(s.course)} · ${esc(s.date)} · Local plan</small></div></div>`).join('')}<div class="row"><span class="activity-dot"></span><div><strong>Jordan broke 80</strong><small>79 at Oak & Pine · Sample activity</small></div></div><div class="row"><span class="activity-dot"></span><div><strong>Alex explored a new course</strong><small>First visit to Meadow Links · Sample activity</small></div></div>${state.invites.map(i=>`<div class="row"><span class="activity-dot"></span><div><strong>Demo invite saved for ${esc(i)}</strong><small>Local only · Nothing sent</small></div></div>`).join('')}</section></div><div>${honoursBoard()}<section class="card section-gap"><div class="card-head"><h2>Challenges</h2></div><p class="muted">Make a challenge with your demo friends.</p>${state.challenges.map(c=>`<div class="year-note"><h3>${esc(c.title)}</h3><small class="muted">With ${esc(c.friend)} · Local demo</small><div class="progress"><i style="width:${Math.min(100,c.done/c.goal*100)}%"></i></div><p>${c.done} / ${c.goal} rounds</p><button class="text small" ${c.done>=c.goal?'disabled':''} onclick="advance('${c.id}')">${c.done>=c.goal?'Challenge complete ✓':'Mark one round complete'}</button></div>`).join('')}<button class="secondary section-gap" onclick="challengeForm()">＋ Create a challenge</button></section></div></div>`,
Profile:()=>`${heading('Make it yours','Your profile.','Player details and saved data.')}<div class="grid"><section class="card"><h2>Player profile</h2><form id="profile-form" class="section-gap" onsubmit="saveProfile(event)"><label>Your name<input name="name" value="${esc(state.profile.name)}" maxlength="50" required></label><label>Home course<input name="home" value="${esc(state.profile.home)}" maxlength="100"></label><label>Annual round goal<input name="goal" type="number" min="1" max="365" value="${state.profile.goal}" required></label><button>Save profile</button></form><div class="progress"><i style="width:${Math.min(100,state.rounds.filter(r=>r.date.startsWith(String(new Date().getFullYear()))).length/state.profile.goal*100)}%"></i></div><p class="muted">${state.rounds.filter(r=>r.date.startsWith(String(new Date().getFullYear()))).length} of ${state.profile.goal} rounds this year</p></section><div><section class="card"><h2>Your data, in your hands.</h2><p class="muted section-gap">Sign in below to save your journal privately in Supabase. Without signing in, records stay in this browser. Export a V7 backup any time.</p><div class="friend-actions"><button onclick="exportData()">Export backup</button><button class="secondary" onclick="document.querySelector('#import').click()">Import V7 backup</button><input hidden id="import" type="file" accept="application/json,.json" onchange="importData(this.files[0])"></div><p class="muted section-gap" style="font-size:12px">Import merges records by ID. Your profile stays as it is. V6 data formats could not be verified because the source was unavailable.</p></section><section class="card section-gap"><h2>Take a look around.</h2><p class="muted section-gap">Add three clearly labeled sample rounds to explore stats, trends, and the Yardage Book.</p><div class="friend-actions"><button class="secondary" onclick="addSamples()">Add sample rounds</button><button class="text" onclick="removeSamples()">Remove sample rounds</button></div></section></div></div>`};
function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button type="button" onclick="modal.close()" aria-label="Close dialog">×</button></div>${body}`;modal.showModal()}
function roundForm(id){clearTimeout(roundCourseTimer);roundCourseRequest++;roundPhotoToken++;roundPhotoBusy=false;let r=id?state.rounds.find(x=>x.id===id):state.draft||{course:'',date:today(),holes:18,tees:'',rating:'',slope:'',score:'',putts:'',notes:'',scores:[]};roundCourseLocation=courseLocation(r);roundLocationName=r.course.trim().toLowerCase();openModal(id?'Your round':'Log a round',`<form id="round-form" onsubmit="saveRound(event,'${id||''}')"><div class="form-grid"><label class="full">Course name<input name="course" required maxlength="100" value="${esc(r.course)}" placeholder="Search by course name" autocomplete="off" aria-describedby="round-course-status" oninput="queueRoundCourses(this.value)"></label><div class="full course-lookup"><p id="round-course-status" class="feature-caption" role="status">Course name and date are required. Enter a score or choose Score not kept.</p><div id="round-course-results" class="course-suggestions"></div></div><div class="full" id="course-card-controls"></div><div class="full round-date"><label>Date<input id="round-date-input" type="text" name="date" required readonly value="${esc(r.date)}" onclick="toggleRoundDatePicker()" onkeydown="roundDateKey(event)" aria-haspopup="dialog" aria-expanded="false" aria-controls="round-date-picker"></label><div id="round-date-picker" class="round-date-picker" role="dialog" aria-label="Choose round date" hidden></div></div><label>Holes<select name="holes" onchange="courseRoundLength(this.value)"><option ${r.holes===18?'selected':''}>18</option><option ${r.holes===9?'selected':''}>9</option></select></label><div class="round-score-field"><label>Total strokes<input type="number" name="score" min="9" max="360" ${r.scoreNotKept?'disabled':'required'} value="${r.score??''}" id="total-score"></label><label class="score-not-kept"><input type="checkbox" name="scoreNotKept" id="score-not-kept" onchange="toggleScoreNotKept(this.checked)" ${r.scoreNotKept?'checked':''}> Score not kept</label><p id="score-not-kept-note" class="feature-caption" hidden></p></div><label class="full round-tees">Tees (optional)<input name="tees" oninput="matchCourseTee(this.value)" maxlength="40" value="${esc(r.tees)}"></label><label>Course rating (optional)<input name="rating" placeholder="From tee card" type="number" min="20" max="90" step="0.1" value="${r.rating??''}"></label><label>Slope rating (optional)<input name="slope" placeholder="From tee card" type="number" min="55" max="155" value="${r.slope??''}"></label><label class="full">Putts (optional)<input name="putts" type="number" min="0" max="180" value="${r.putts??''}"></label><label class="full">Round notes<textarea name="notes" maxlength="2000" placeholder="A shot, a moment, a memory…">${esc(r.notes)}</textarea></label></div><details ${r.scores?.some(x=>x!==null)?'open':''}><summary>Hole-by-hole entry (optional)</summary><p class="muted" style="font-size:12px;margin:12px 0">Fill every hole to calculate your total automatically. Partial hole entries stay as notes; enter a total above.</p><div id="holes" class="hole-grid"></div></details>${roundExtrasEditor(r)}${roundPhotoEditor()}<div class="form-actions">${id?`<button type="button" class="text" onclick="deleteRound('${id}')">Delete</button>`:'<button type="button" class="secondary" onclick="saveDraft()">Save draft</button>'}<button id="save-round-button">Save round</button></div></form>`);drawHoles(r.holes,r.scores||[]);roundPhotoDraft=[...(r.photos||[])];drawRoundPhotos();if(r.scoreNotKept)toggleScoreNotKept(true)}
function drawHoles(n,values){let current=values||[...document.querySelectorAll('.hole-score')].map(x=>x.value);document.querySelector('#holes').innerHTML=Array.from({length:+n},(_,i)=>`<label>Hole ${i+1}<input class="hole-score" ${document.querySelector('#score-not-kept')?.checked?'disabled':''} aria-label="Hole ${i+1} strokes" type="number" min="1" max="20" value="${current[i]||''}" oninput="sumHoles()"></label>`).join('');}
function sumHoles(){if(document.querySelector('#score-not-kept')?.checked)return;let scores=[...document.querySelectorAll('.hole-score')].map(x=>+x.value);if(scores.every(x=>x>=1&&x<=20))document.querySelector('#total-score').value=scores.reduce((a,b)=>a+b,0)}
function readRound(){let f=new FormData(document.querySelector('#round-form'));return {...(roundCourseLocation&&f.get('course').trim().toLowerCase()===roundLocationName?{location:roundCourseLocation}:{}),course:f.get('course').trim(),date:f.get('date'),holes:+f.get('holes'),tees:f.get('tees').trim(),score:f.get('scoreNotKept')==='on'?null:+f.get('score'),scoreNotKept:f.get('scoreNotKept')==='on',rating:f.get('rating')===''?null:+f.get('rating'),slope:f.get('slope')===''?null:+f.get('slope'),putts:f.get('putts')===''?null:+f.get('putts'),notes:f.get('notes'),photos:[...roundPhotoDraft],scores:[...document.querySelectorAll('.hole-score')].map(x=>f.get('scoreNotKept')==='on'?null:x.value?+x.value:null)}}
async function saveRound(e,id){e.preventDefault();if(roundPhotoBusy)return toast("Wait for photos to finish preparing.");const post=document.querySelector("#post-round-choice")?.checked;let r=readRound();if(!r.course||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||(!r.scoreNotKept&&!Number.isInteger(r.score)))return toast('Add a course name, date, and total score.');if(!r.scoreNotKept&&r.score<r.holes)return toast('Total strokes must be at least the number of holes.');if(!r.scoreNotKept&&r.scores.every(x=>x!==null)&&r.score!==r.scores.reduce((a,b)=>a+b,0))return toast('Total strokes must match your hole scores.');const before=JSON.stringify(state);if(!id)id=crypto.randomUUID();const existing=state.rounds.some(x=>x.id===id);if(existing){let i=state.rounds.findIndex(x=>x.id===id);state.rounds[i]={...state.rounds[i],...r}}else{state.rounds.push({...r,id});state.draft=null}if(JSON.stringify(state).length>3500000||!persist()){state=JSON.parse(before);return toast('This device is low on storage. Remove a photo or export a backup before saving.')}modal.close();render();toast('Round saved privately.');if(post){try{await publishRoundToFriends(state.rounds.find(x=>x.id===id));return 'posted'}catch(error){toast(error.message);return false}}}
function saveDraft(){if(roundPhotoBusy)return toast('Wait for photos to finish preparing.');const before=JSON.stringify(state);state.draft=readRound();if(JSON.stringify(state).length>3500000||!persist()){state=JSON.parse(before);return toast('Not enough device storage. Remove a photo and try again.')}modal.close();render();toast('Draft saved. Resume from Home or Log a round.')}
function deleteRound(id){openModal('Delete this round?',`<p>This removes the round from your journal, including its friends-only post and Supabase copy when signed in. Export a backup first if you want to keep a copy.</p><div class="form-actions"><button class="secondary" onclick="modal.close()">Keep round</button><button onclick="deleteSavedRound('${id}')">Delete round</button></div>`)}
function noteForm(id){let n=state.notes.find(n=>n.id===id)||{date:today(),title:'',text:''};openModal('A moment to remember',`<form onsubmit="saveNote(event,'${id||''}')"><label>Date<input name="date" type="date" required value="${esc(n.date)}"></label><label>Title<input name="title" required maxlength="100" value="${esc(n.title)}" placeholder="That one perfect shot"></label><label>Your memory<textarea name="text" required maxlength="3000" rows="5">${esc(n.text)}</textarea></label><button>Save memory</button></form>`)}
function saveNote(e,id){e.preventDefault();let f=new FormData(e.target),n={id:id||crypto.randomUUID(),date:f.get('date'),title:f.get('title').trim(),text:f.get('text').trim()};if(!n.title||!n.text)return;state.notes=state.notes.filter(x=>x.id!==id);state.notes.push(n);year=n.date.slice(0,4);persist();modal.close();render();toast('Memory saved')}
function friendOptions(id){return state.friends.map(f=>`<option value="${f.id}" ${id===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}
function inviteForm(){openModal('Invite a golf friend',`<p class="notice">Local demo · This saves a placeholder invite on this device. Nothing is sent.</p><form onsubmit="invite(event)"><label>Friend’s name or email<input name="person" required maxlength="100" placeholder="Who’s joining your next round?"></label><button>Save demo invite</button></form>`)}
function invite(e){e.preventDefault();let v=new FormData(e.target).get('person').trim();if(!v)return;state.invites.push(v);persist();modal.close();render();toast('Demo invite saved locally. Nothing sent.')}
function sharedForm(id){openModal('Plan a shared round',`<p class="notice">Local demo · Save a plan here. Your friend won’t receive a message.</p><form onsubmit="saveShared(event)"><label>Play with<select name="friend">${friendOptions(id)}</select></label><label>Course<input name="course" required maxlength="100" placeholder="Pick your next fairway"></label><label>Date<input name="date" type="date" required value="${today()}"></label><button>Save local plan</button></form>`)}
function saveShared(e){e.preventDefault();let f=new FormData(e.target);state.shared.push({id:crypto.randomUUID(),friend:state.friends.find(x=>x.id===f.get('friend')).name,course:f.get('course').trim(),date:f.get('date')});persist();modal.close();render();toast('Shared round plan saved locally')}
function challengeForm(){openModal('A friendly challenge',`<p class="notice">Local demo · Progress is marked manually and saved on this device.</p><form onsubmit="saveChallenge(event)"><label>Challenge name<input name="title" required maxlength="100" placeholder="Play more autumn golf"></label><label>Challenge with<select name="friend">${friendOptions()}</select></label><label>Round target<input name="goal" type="number" min="1" max="100" value="3" required></label><button>Create demo challenge</button></form>`)}
function saveChallenge(e){e.preventDefault();let f=new FormData(e.target);state.challenges.push({id:crypto.randomUUID(),title:f.get('title').trim(),friend:state.friends.find(x=>x.id===f.get('friend')).name,goal:+f.get('goal'),done:0});persist();modal.close();render();toast('Demo challenge created')}
function advance(id){let c=state.challenges.find(c=>c.id===id);c.done=Math.min(c.goal,c.done+1);persist();render();toast(c.done===c.goal?'Challenge complete!':'Challenge progress saved')}
function saveProfile(e){e.preventDefault();let f=new FormData(e.target),name=f.get('name').trim();if(!name)return toast('Enter your name');state.profile={name,home:f.get('home').trim(),goal:+f.get('goal')};persist();render();toast('Profile saved')}
function exportData(){let blob=new Blob([JSON.stringify({format:'dogleg-v7',version:7,data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='dogleg-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')}
function validBackup(s){const str=(x,n=3000)=>typeof x==='string'&&x.length<=n;const num=(x,a,b)=>Number.isFinite(x)&&x>=a&&x<=b;const date=x=>str(x,10)&&/^\d{4}-\d{2}-\d{2}$/.test(x);const arr=(x,test)=>Array.isArray(x)&&x.length<=5000&&x.every(test);const id=x=>str(x,100)&&/^[\w-]+$/.test(x);return s&&arr(s.rounds,r=>id(r.id)&&str(r.course,100)&&date(r.date)&&[9,18].includes(r.holes)&&((r.scoreNotKept===true&&r.score===null)||(r.scoreNotKept!==true&&num(r.score,r.holes,360)))&&(r.scoreNotKept===undefined||typeof r.scoreNotKept==='boolean')&&(r.rating===null||num(r.rating,20,90))&&(r.slope===null||num(r.slope,55,155))&&str(r.tees,40)&&(r.putts===null||num(r.putts,0,180))&&str(r.notes)&&(r.location===undefined||(r.location&&Number.isFinite(r.location.lat)&&Math.abs(r.location.lat)<=90&&Number.isFinite(r.location.lon)&&Math.abs(r.location.lon)<=180&&(r.location.address===undefined||str(r.location.address,500))))&&(r.courseCard===undefined||validCourseCard(r.courseCard))&&(r.courseNine===undefined||['front','back'].includes(r.courseNine))&&(r.extras===undefined||validRoundExtras(r.extras))&&validRoundPhotos(r.photos)&&arr(r.scores,x=>x===null||num(x,1,20)))&&arr(s.notes,n=>id(n.id)&&date(n.date)&&str(n.title,100)&&str(n.text))&&arr(s.friends,f=>id(f.id)&&str(f.name,100)&&num(f.hcp,-10,54)&&num(f.score,18,360))&&arr(s.challenges,c=>id(c.id)&&str(c.title,100)&&str(c.friend,100)&&num(c.goal,1,100)&&num(c.done,0,c.goal))&&arr(s.shared,r=>id(r.id)&&str(r.friend,100)&&str(r.course,100)&&date(r.date))&&arr(s.invites,i=>str(i,100))}
async function importData(file){if(!file)return;try{if(file.size>10000000)throw Error();let b=JSON.parse(await file.text());if(b.format!=='dogleg-v7'||!validBackup(b.data))throw Error();let incoming=b.data;for(let k of ['rounds','notes','friends','challenges','shared']){let map=new Map(state[k].map(x=>[x.id,x]));for(let x of incoming[k])if(!map.has(x.id))map.set(x.id,x);state[k]=[...map.values()]}state.invites=[...new Set([...state.invites,...incoming.invites])];persist();render();toast('Backup merged. Existing records kept.')}catch(e){toast('Could not import. Choose a valid Dogleg V7 backup.')}}
function addSamples(){let courses=['Meadow Links','Oak & Pine','Meadow Links'],scores=[94,89,86];for(let i=0;i<3;i++)if(!state.rounds.some(r=>r.id==='sample-'+i))state.rounds.push({id:'sample-'+i,course:courses[i],date:new Date(new Date().getFullYear(),8,5+i*8).toLocaleDateString('en-CA'),holes:18,tees:'White',score:scores[i],rating:71.6,slope:124,putts:36-i,notes:'Sample round for exploring Dogleg.',scores:[],sample:true});persist();render();toast('Three sample rounds added')}
function removeSamples(){state.rounds=state.rounds.filter(r=>!r.sample);persist();render();toast('Sample rounds removed')}
