if(typeof openModal==='function'){
let dialogPagePosition=null;
const unlockedOpenModal=openModal;
openModal=function(title,body){
 if(!modal.open&&dialogPagePosition===null){
  dialogPagePosition={y:window.scrollY,position:document.body.style.position,top:document.body.style.top,width:document.body.style.width};
  document.body.style.position='fixed';document.body.style.top='-'+dialogPagePosition.y+'px';document.body.style.width='100%';
 }
 unlockedOpenModal(title,body);modal.scrollTop=0;
};
modal.addEventListener('close',()=>{
 if(modal.open||dialogPagePosition===null)return;
 const saved=dialogPagePosition;dialogPagePosition=null;
 Object.assign(document.body.style,{position:saved.position,top:saved.top,width:saved.width});
 window.scrollTo({top:saved.y,behavior:'instant'});
});

}


function toggleScoreNotKept(checked){const form=document.querySelector('#round-form');if(!form)return;const score=form.querySelector('[name=score]');score.required=!checked;score.disabled=checked;form.querySelectorAll('.hole-score').forEach(input=>input.disabled=checked);const post=form.querySelector('#post-round-choice');if(post){if(checked)post.checked=false;post.disabled=checked||!cloudUser}const note=form.querySelector('#score-not-kept-note');if(note){note.hidden=!checked;note.textContent='This round counts toward rounds played and your map, but not scoring statistics.'+(cloudUser?' Rounds without a score are saved privately.':'')}}
let roundDateView=null;
function roundDateParts(value){const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(value||'');if(!match)return null;const year=+match[1],month=+match[2]-1,day=+match[3],date=new Date(Date.UTC(year,month,day));return date.getUTCFullYear()===year&&date.getUTCMonth()===month&&date.getUTCDate()===day?{year,month,day}:null}
function roundDateIso(year,month,day){return new Date(Date.UTC(year,month,day)).toISOString().slice(0,10)}
function roundCalendarMarkup(value,year,month,focusDate=value){const first=new Date(Date.UTC(year,month,1)).getUTCDay(),days=new Date(Date.UTC(year,month+1,0)).getUTCDate(),months=Array.from({length:12},(_,m)=>new Date(2000,m,1).toLocaleString('en-US',{month:'long'})),currentYear=new Date().getFullYear(),years=Array.from({length:Math.max(currentYear+5,year)-Math.min(1900,year)+1},(_,i)=>Math.min(1900,year)+i),todayIso=typeof today==='function'?today():'';const focus=roundDateParts(focusDate);if(!focus||focus.year!==year||focus.month!==month)focusDate=roundDateIso(year,month,1);return '<div class="date-calendar-heading"><button type="button" onclick="shiftRoundDateMonth(-1)" aria-label="Previous month">‹</button><strong aria-live="polite">'+months[month]+' '+year+'</strong><button type="button" onclick="shiftRoundDateMonth(1)" aria-label="Next month">›</button></div><div class="date-calendar-selects"><select aria-label="Calendar month" onchange="setRoundDateView(roundDateView.year,+this.value)">'+months.map((name,m)=>'<option value="'+m+'" '+(m===month?'selected':'')+'>'+name+'</option>').join('')+'</select><select aria-label="Calendar year" onchange="setRoundDateView(+this.value,roundDateView.month)">'+years.map(y=>'<option '+(y===year?'selected':'')+'>'+y+'</option>').join('')+'</select></div><div class="date-calendar-grid">'+['Su','Mo','Tu','We','Th','Fr','Sa'].map(d=>'<span class="date-weekday" aria-hidden="true">'+d+'</span>').join('')+Array.from({length:first},()=>'<span aria-hidden="true"></span>').join('')+Array.from({length:days},(_,i)=>{const iso=roundDateIso(year,month,i+1),label=new Date(iso+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});return '<button type="button" data-round-date="'+iso+'" onclick="chooseRoundDate(this.dataset.roundDate)" onkeydown="roundCalendarDayKey(event,this.dataset.roundDate)" aria-label="'+label+'" aria-pressed="'+(iso===value)+'" tabindex="'+(iso===focusDate||(!roundDateParts(focusDate)&&i===0)?'0':'-1')+'" class="'+(iso===value?'is-selected ':'')+(iso===todayIso?'is-today':'')+'">'+(i+1)+'</button>'}).join('')+'</div><div class="date-calendar-footer"><button type="button" class="text small" onclick="chooseRoundDate(today())">Today</button><button type="button" class="text small" onclick="toggleRoundDatePicker(false)">Close calendar</button></div>'}
function setRoundDateView(year,month,focusDate){const date=new Date(Date.UTC(year,month,1));roundDateView={year:date.getUTCFullYear(),month:date.getUTCMonth()};const root=document.querySelector('#round-date-picker'),input=document.querySelector('#round-date-input');if(!root||!input)return;root.innerHTML=roundCalendarMarkup(input.value,roundDateView.year,roundDateView.month,focusDate||input.value);if(focusDate)root.querySelector('[data-round-date="'+focusDate+'"]')?.focus({preventScroll:true})}
function toggleRoundDatePicker(force){const root=document.querySelector('#round-date-picker'),input=document.querySelector('#round-date-input');if(!root||!input)return;const open=force===undefined?root.hidden:force;root.hidden=!open;input.setAttribute('aria-expanded',String(open));if(open){const selected=roundDateParts(input.value)||roundDateParts(today());setRoundDateView(selected.year,selected.month);root.querySelector('[aria-pressed="true"]')?.focus({preventScroll:true});root.scrollIntoView({block:'nearest',behavior:'auto'})}else input.focus({preventScroll:true})}
function shiftRoundDateMonth(delta){if(roundDateView)setRoundDateView(roundDateView.year,roundDateView.month+delta)}
function chooseRoundDate(iso){if(!roundDateParts(iso))return;const input=document.querySelector('#round-date-input');if(!input)return;input.value=iso;toggleRoundDatePicker(false)}
function roundDateKey(event){if(['Enter',' ','ArrowDown'].includes(event.key)){event.preventDefault();toggleRoundDatePicker(true)}else if(event.key==='Escape'){event.preventDefault();toggleRoundDatePicker(false)}}
function roundCalendarDayKey(event,iso){if(event.key==='Escape'){event.preventDefault();toggleRoundDatePicker(false);return}const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[event.key];if(delta===undefined)return;event.preventDefault();const date=new Date(iso+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+delta);const next=date.toISOString().slice(0,10),parts=roundDateParts(next);setRoundDateView(parts.year,parts.month,next)}

// Courses, bounded photo attachments, and explicit accepted-friends posts.
let roundPhotoDraft=[],roundPhotoBusy=false,roundPhotoToken=0;
function resetAccountEditors(){roundPhotoToken++;roundPhotoDraft=[];roundPhotoBusy=false;clearTimeout(roundCourseTimer);roundCourseRequest++;if(modal.open)modal.close()}
function validRoundPhotos(photos){return photos===undefined||Array.isArray(photos)&&photos.length<=3&&photos.every(p=>typeof p==='string'&&p.length<=90000&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(p))}
function roundPhotoEditor(){return `<section class="round-photo-section"><h3>Photos from your round</h3><p class="feature-caption">Add up to 3 photos. They stay private unless you choose to post below.</p><label>Add photos<input id="round-photo-files" type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="attachRoundPhotos(this.files)"></label><div id="round-photo-status" class="feature-caption" role="status"></div><div id="round-photo-previews" class="round-photo-grid"></div><label class="post-choice"><input id="post-round-choice" type="checkbox" onchange="document.querySelector('#save-round-button').textContent=this.checked?'Save & post':'Save round'" ${cloudUser?'':'disabled'}> Post this round to accepted friends</label><p class="feature-caption">${cloudUser?'Shares your name, course, score, date, tees, notes and attached photos. Posting again replaces the previous post. Changes stay private until you post again; remove earlier posts in Friends.':'Log in to post. You can still save rounds and photos on this device.'}</p></section>`}
function drawRoundPhotos(){const el=document.querySelector('#round-photo-previews');if(el)el.innerHTML=roundPhotoDraft.map((p,i)=>`<figure><img src="${p}" alt="Round photo ${i+1}"><button class="secondary small" type="button" onclick="removeRoundPhoto(${i})" aria-label="Remove photo ${i+1}">Remove</button></figure>`).join('')}
function removeRoundPhoto(i){if(roundPhotoBusy)return;roundPhotoDraft.splice(i,1);drawRoundPhotos()}
async function compressRoundPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw Error('Choose JPG, PNG or WebP photos under 15 MB each.');const bitmap=await createImageBitmap(file);try{if(!bitmap.width||!bitmap.height||bitmap.width*bitmap.height>80000000)throw Error('This image is too large to process. Choose a smaller copy.');let size=1100;for(let pass=0;pass<7;pass++){const scale=Math.min(1,size/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.72);if(data.length<=90000)return data;size=Math.floor(size*.78)}throw Error('Could not resize this photo. Try another image.')}finally{bitmap.close()}}
async function attachRoundPhotos(files){if(roundPhotoBusy)return;const input=document.querySelector('#round-photo-files'),status=document.querySelector('#round-photo-status'),token=roundPhotoToken;if(files.length+roundPhotoDraft.length>3){status.textContent='You can attach 3 photos per round. Remove one before adding another.';input.value='';return}roundPhotoBusy=true;input.disabled=true;status.textContent='Preparing photos…';try{const ready=[];for(const file of files)ready.push(await compressRoundPhoto(file));if(token!==roundPhotoToken||!document.querySelector('#round-photo-previews'))return;roundPhotoDraft.push(...ready);drawRoundPhotos();status.textContent='Photos ready. Save your round to keep them.'}catch(e){if(token===roundPhotoToken)status.textContent=e.message||'Could not open the photo.'}finally{if(token===roundPhotoToken){roundPhotoBusy=false;input.disabled=false;input.value=''}}}
function coursesView(){const records=state.rounds.filter(r=>!r.sample),courses=[...new Set(records.map(r=>r.course))].sort((a,b)=>a.localeCompare(b));return `${heading('Courses','Where are you playing next?','Find a course or revisit one you’ve played.','<button onclick="clubSearch()">Find a course</button>')}<section class="card course-discovery"><div class="course-discovery-intro"><h2>Find your next round</h2><p class="muted">Search courses around the world, then start a scorecard.</p></div><form onsubmit="event.preventDefault();openCourseDiscovery()"><label>Course name<input id="courses-query" required minlength="3" maxlength="100" placeholder="Course or club name"></label><button>Search courses</button></form></section><div class="section-title section-gap"><h2>Your courses</h2><button class="secondary" onclick="go('Passport')">Open Yardage Book</button></div><div class="course-collection">${courses.length?courses.map((name,i)=>{const rounds=records.filter(r=>r.course===name),latest=[...rounds].sort((a,b)=>b.date.localeCompare(a.date))[0],best=rounds.filter(r=>r.holes===18&&Number.isFinite(r.score)).reduce((b,r)=>Math.min(b,r.score),Infinity);return `<section class="card"><span class="badge">${rounds.length} ${rounds.length===1?'round':'rounds'}</span><h2><span class="course-inline-badge">${courseBadge(latest)}</span>${esc(name)}</h2><p class="feature-caption">Last played ${esc(latest.date)}${best!==Infinity?' · Best 18: '+best:''}</p><div class="friend-actions"><button onclick="openKnownCourse(${i})">Explore course</button><button class="secondary" onclick="logKnownCourse(${i})">Log a round</button><button class="secondary" onclick="viewKnownCourse(${i})">View rounds</button></div></section>`}).join(''):'<section class="card empty"><h3>Your course collection starts with a round.</h3><p>Courses you play will appear here automatically.</p><button class="section-gap" onclick="roundForm()">Log a round</button></section>'}</div>`}
function knownCourseNames(){return [...new Set(state.rounds.filter(r=>!r.sample).map(r=>r.course))].sort((a,b)=>a.localeCompare(b))}
function logKnownCourse(i){const name=knownCourseNames()[i];if(!name)return;roundForm();fillRoundCourse(savedCourseMatches(state.rounds,name).find(c=>c.name.toLowerCase()===name.toLowerCase()))}
function viewKnownCourse(i){const name=knownCourseNames()[i];if(name){trackingFilters={query:name,year:'all',holes:'all',sort:'newest'};go('Rounds')}}
function openCourseDiscovery(){const name=document.querySelector('#courses-query').value.trim();clubSearch();document.querySelector('#club-query').value=name;searchClubs()}
let socialConnections=[],socialPosts=[],socialOwner=null,socialStatus='Open your feed to see recent rounds.',socialLoading=false,socialSequence=0;
function socialReset(){socialConnections=[];socialPosts=[];socialOwner=null;socialLoading=false;socialSequence++}
function socialPhotoMarkup(photos){return (photos||[]).filter(p=>validRoundPhotos([p])).map((p,i)=>`<img loading="lazy" src="${p}" alt="Round photo ${i+1}">`).join('')}
function socialCourseIdentity(post){const p=post.payload||{},own=post.user_id===cloudUser?.id?state.rounds.find(r=>r.id===post.round_id):null;return {course:p.course,courseId:p.courseId||(own?.course===p.course?own.courseCard?.courseId:null),location:p.location||(own?.course===p.course?own.location:null)}}
function friendsFeed(){if(!cloudUser)return `${heading('Friends','Good rounds are better together.','Connect with friends to share scores and photos.')}<section class="card empty"><h2>Your friends’ rounds belong here.</h2><p class="section-gap">Log in to send friend requests and post to accepted friends.</p><button class="section-gap" onclick="openAccount()">Log in or create an account</button></section>`;if(socialOwner!==cloudUser.id){socialReset();socialOwner=cloudUser.id}const id=cloudUser.id;return `${heading('Friends','Around the course.','Rounds and photos shared with accepted friends only.','<button onclick="loadSocial()">Refresh feed</button>')}<p id="social-status" class="feature-caption" role="status">${esc(socialStatus)}</p><div class="friend-grid"><section class="card"><h2>Find your golf friends</h2><label class="section-gap">Your friend code<input readonly value="${id}" aria-label="Your friend code"></label><p class="feature-caption">Give this code to someone you want to connect with. It does not sign anyone into your account.</p><form onsubmit="requestGolfFriend(event)"><label>Their friend code<input name="code" required placeholder="Paste your friend’s code" autocomplete="off"></label><button>Send friend request</button></form><div class="section-gap"><h3>Connections</h3>${socialConnections.length?socialConnections.map((c,i)=>{const incoming=c.recipient===id,pending=c.status==='pending',name=incoming?c.requester_name:c.recipient_name;return `<div class="row"><div class="grow"><strong>${esc(name)}</strong><small>${pending?(incoming?'Wants to connect':'Request sent'):'Accepted friend'}</small></div>${pending&&incoming?`<button class="small" onclick="acceptGolfFriend(${i})">Accept</button>`:''}<button class="text small" onclick="removeGolfFriend(${i})">${pending?'Dismiss':'Disconnect'}</button></div>`}).join(''):'<p class="feature-caption">No connections yet. Share your code to get started.</p>'}</div></section><section><div class="section-title"><h2>The latest rounds</h2><button class="text" onclick="roundForm()">Add yours</button></div>${socialPosts.length?socialPosts.map((post,i)=>{const p=post.payload;return `<article class="card round-post"><div class="card-head"><div><strong>${esc(p.name)}</strong><p class="feature-caption">${esc(p.date)} · Accepted friends</p></div><span class="score">${p.score===null?'Score not kept':esc(p.score)}</span></div><h2 class="post-course-title"><span class="course-inline-badge">${courseBadge(socialCourseIdentity(post))}</span>${esc(p.course)}</h2><p class="feature-caption">${esc(p.holes)} holes · ${esc(p.tees)} tees</p>${p.notes?`<p class="post-notes">${esc(p.notes)}</p>`:''}<div class="post-photos">${socialPhotoMarkup(p.photos)}</div>${post.user_id===id?`<button class="text section-gap" onclick="unpostRound(${i})">Remove from feed</button>`:''}</article>`}).join(''):'<section class="card empty"><h3>A quiet clubhouse, for now.</h3><p>Refresh to load posts. When you or an accepted friend posts a round, it will appear here.</p><button class="section-gap" onclick="loadSocial()">Load feed</button></section>'}</section></div>`}
function socialMessage(message){socialStatus=message;const el=document.querySelector('#social-status');if(el)el.textContent=message}
async function loadSocial(){if(!cloudUser||socialLoading)return;const owner=cloudUser.id,token=++socialSequence;socialLoading=true;socialMessage('Loading friends and rounds…');try{const client=await cloudInit();const [connections,posts]=await Promise.all([client.from('dogleg_connections').select('*').order('created_at',{ascending:false}),client.from('dogleg_round_posts').select('*').order('created_at',{ascending:false}).limit(30)]);if(connections.error||posts.error)throw connections.error||posts.error;if(cloudUser?.id!==owner||token!==socialSequence)return;socialOwner=owner;socialConnections=connections.data;socialPosts=posts.data;socialStatus='Up to date · Only accepted friends can see posted rounds.';if(tab==='Friends')render()}catch(e){if(cloudUser?.id===owner&&token===socialSequence)socialMessage('Could not load the feed. Check your connection and refresh.')}finally{if(token===socialSequence)socialLoading=false}}
async function requestGolfFriend(event){event.preventDefault();if(!cloudUser)return;const code=new FormData(event.target).get('code').trim();if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(code)||code.toLowerCase()===cloudUser.id)return socialMessage('Enter another golfer’s valid friend code.');const owner=cloudUser.id,name=state.profile.name,button=event.target.querySelector('button');button.disabled=true;try{const client=await cloudInit();if(owner!==cloudUser?.id)return;const {error}=await client.from('dogleg_connections').insert({requester:owner,recipient:code,requester_name:name,status:'pending'});if(error)throw error;event.target.reset();await loadSocial()}catch(e){socialMessage('Could not send the request. Check the code; you may already have a connection or request.')}finally{button.disabled=false}}
async function acceptGolfFriend(i){const c=socialConnections[i];if(!c||c.recipient!==cloudUser?.id)return;try{const client=await cloudInit(),{error}=await client.from('dogleg_connections').update({status:'accepted',recipient_name:state.profile.name}).eq('id',c.id);if(error)throw error;await loadSocial()}catch(e){socialMessage('Could not accept the request. Please refresh and try again.')}}
function removeGolfFriend(i){const c=socialConnections[i];if(!c)return;openModal('Remove this connection?',`<p>You will no longer be able to load each other’s posted rounds. Photos already viewed or saved cannot be recalled.</p><div class="form-actions"><button class="secondary" onclick="modal.close()">Keep connection</button><button onclick="confirmRemoveGolfFriend('${c.id}')">Remove connection</button></div>`)}
async function confirmRemoveGolfFriend(id){const owner=cloudUser?.id;try{const client=await cloudInit();if(!owner||owner!==cloudUser?.id)return;const {error}=await client.from('dogleg_connections').delete().eq('id',id);if(error)throw error;if(owner!==cloudUser?.id)return;modal.close();socialPosts=[];await loadSocial()}catch(e){toast('Could not remove the connection. Try again.')}}
function roundPostPayload(round,name){return {name,course:round.course,date:round.date,holes:round.holes,score:round.score,tees:round.tees,notes:round.notes,photos:round.photos||[],...(validCourseCard(round.courseCard)?{courseId:round.courseCard.courseId}:{}),...(validCourseLocation(round.location)?{location:round.location}:{})}}
async function deleteSavedRound(id){const owner=cloudUser?.id,epoch=cloudEpoch;try{if(owner&&!id.startsWith('sample-')){const client=await cloudInit();if(owner!==cloudUser?.id||epoch!==cloudEpoch)return;const {error}=await client.from('dogleg_round_posts').delete().eq('user_id',owner).eq('round_id',id);if(error)throw error}if(owner!==cloudUser?.id||epoch!==cloudEpoch)return;const before=JSON.stringify(state);state.rounds=state.rounds.filter(r=>r.id!==id);if(!persist()){state=JSON.parse(before);return toast('Could not save the deletion on this device.')}socialPosts=[];modal.close();render();toast('Round deleted.')}catch(e){toast('Reconnect before deleting this round so its shared post can be removed too.')}}
async function publishRoundToFriends(round){if(!cloudUser)throw Error('Log in to post your round.');if(round.sample)throw Error('Sample rounds cannot be posted.');const owner=cloudUser.id,payload=roundPostPayload(round,state.profile.name),client=await cloudInit();if(owner!==cloudUser?.id)throw Error('Account changed. Open your round and post again.');const {error}=await client.from('dogleg_round_posts').upsert({user_id:owner,round_id:round.id,payload,created_at:new Date().toISOString()},{onConflict:'user_id,round_id'});if(error)throw Error('Round saved privately. Posting failed; reopen it and try again.');if(cloudUser?.id===owner){socialPosts=[];toast('Round posted to accepted friends.')}}
function unpostRound(i){const post=socialPosts[i];if(!post||post.user_id!==cloudUser?.id)return;openModal('Remove this post?',`<p>Your private round and photos will stay in your journal. Accepted friends will no longer be able to load this post.</p><div class="form-actions"><button class="secondary" onclick="modal.close()">Keep post</button><button onclick="confirmUnpostRound('${post.round_id}')">Remove post</button></div>`)}
async function confirmUnpostRound(id){const owner=cloudUser?.id;try{const client=await cloudInit();if(!owner||owner!==cloudUser?.id)return;const {error}=await client.from('dogleg_round_posts').delete().eq('user_id',owner).eq('round_id',id);if(error)throw error;if(owner!==cloudUser?.id)return;modal.close();socialPosts=[];await loadSocial()}catch(e){toast('Could not remove the post. Try again.')}}
if(typeof views!=='undefined'){views.Courses=coursesView;views.Friends=friendsFeed;icons.Courses='<path d="M5 18V3m0 0 11 3-11 4M2 18h12"/>';const originalGo=go;go=function(t){originalGo(t);if(t==='Friends'&&cloudUser)loadSocial()}}
const roundSocialStyle=document.createElement('style');roundSocialStyle.textContent=`.round-photo-section{border-top:1px solid var(--line);margin:20px 0;padding-top:20px}.round-photo-grid,.post-photos{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.round-photo-grid figure{margin:0;min-width:0}.round-photo-grid img,.post-photos img{width:100%;height:150px;object-fit:cover;border-radius:10px}.round-photo-grid button{width:100%;margin-top:5px}.post-photos img{height:auto;max-height:480px;object-fit:contain;background:#eef5f5}.post-photos:has(img:only-child){grid-template-columns:1fr}.post-choice{display:flex;gap:10px;align-items:center;margin-top:20px}.post-choice input{width:20px;min-height:20px;margin:0}.course-collection{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.course-collection h2{margin-top:16px;overflow-wrap:anywhere}.course-discovery form{display:flex;align-items:end;gap:12px;margin-top:20px}.course-discovery label{flex:1;margin:0}.course-discovery button{min-height:48px}.round-post{margin-bottom:20px}.round-post .card-head{margin-bottom:12px}.post-notes{white-space:pre-wrap;overflow-wrap:anywhere;margin:15px 0}.round-post .feature-caption{margin:4px 0}.round-post .post-photos{margin-top:15px}@media(max-width:850px){nav button.contains-passport{background:#e3f2ed;color:#075747}nav .mobile-passport{display:none}.course-collection{grid-template-columns:1fr}.course-discovery form{display:block}.course-discovery button{margin-top:12px;width:100%}.round-photo-grid img{height:95px}.post-photos{grid-template-columns:1fr}.post-photos img{max-height:360px}}`;document.head.append(roundSocialStyle);

// A focused launch screen and a private, location-aware Yardage Book.
let bookSection='map',bookYear=String(new Date().getFullYear()),bookSelected=0,bookMap=null,bookEpoch=0,bookLoader=null,bookLink=null;
function bookCourses(records=state.rounds){const groups=new Map();for(const r of records.filter(r=>!r.sample)){const key=r.course.trim().toLowerCase();if(!groups.has(key))groups.set(key,{name:r.course,rounds:[],location:null});const c=groups.get(key);c.rounds.push(r);if(validCourseLocation(r.location))c.location=r.location}return [...groups.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function focusedHome(){const records=state.rounds.filter(r=>!r.sample),latest=[...records].reverse().sort((a,b)=>b.date.localeCompare(a.date))[0],year=String(new Date().getFullYear()),season=records.filter(r=>r.date.startsWith(year));return `<div class="focused-home"><p class="home-hello">Good to see you, ${esc(state.profile.name)}.</p><section class="hero home-launch"><div><span class="eyebrow">A life well played</span><h1>Good round?<br>Keep the feeling.</h1><p>The score. The shots. The people.<br>A little space for every round.</p><button class="log-primary" onclick="roundForm()">${golfMark('flag')}${state.draft?'Resume your round':'Log a round'}</button></div></section><div class="home-utilities"><button class="text" onclick="scanForm()">Scan a scorecard</button><button class="text" onclick="addMenu()">More ways to add</button></div>${latest?`<button class="home-last" onclick="roundForm('${latest.id}')"><span class="home-score">${latest.score??'—'}</span><span><small>LAST ROUND · ${esc(latest.date)}</small><strong>${esc(latest.course)}</strong><small>${latest.holes} holes · Open scorecard</small></span>${golfMark('arrow')}</button>`:'<p class="home-empty">Your first round is the start of a good story.</p>'}<button class="home-book" onclick="go('Passport')"><span>${golfMark('pin')}</span><span><strong>Your Yardage Book</strong><small>${season.length} rounds this year · ${bookCourses(records).length} courses explored<br>Your places, progress and good memories.</small></span>${golfMark('arrow')}</button></div>`}
function animateBookChange(){const el=document.querySelector('.yardage-book');if(el&&!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate?.([{opacity:.45,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:200})}
function selectBookSection(section){bookSection=section;render();animateBookChange()}
function setBookYear(value){bookYear=value;bookSelected=0;render();animateBookChange()}
function activeBookYear(){return bookSection==='map'&&typeof atlasMapYear!=='undefined'?atlasMapYear:bookYear}
function bookRecords(){const selectedYear=activeBookYear();return state.rounds.filter(r=>!r.sample&&(!selectedYear||r.date.startsWith(selectedYear)))}
function bookCourseDetail(){const c=bookCourses(bookRecords())[bookSelected];if(!c)return '<p class="muted">Log a round to start exploring your golf story.</p>';const full=c.rounds.filter(r=>r.holes===18&&Number.isFinite(r.score)),photos=c.rounds.flatMap(r=>r.photos||[]).slice(0,3);return `<span class="eyebrow">${c.rounds.length} ${c.rounds.length===1?'visit':'visits'}</span><h2>${esc(c.name)}</h2><p class="muted">${c.location?esc(c.location.address||'Course location saved'):'This course hasn’t been placed on your map yet.'}</p><p>${full.length?'Best 18: <strong>'+Math.min(...full.map(r=>r.score))+'</strong> · ':''}Last played ${esc(c.rounds.map(r=>r.date).sort().at(-1))}</p>${photos.length?`<div class="book-photos">${photos.map((p,i)=>`<img src="${p}" alt="Round memory ${i+1}">`).join('')}</div>`:''}<div class="friend-actions">${c.location?'':`<button onclick="placeBookCourse()">Place on map</button>`}<button class="secondary" onclick="bookRoundHistory()">View rounds</button><button class="text" onclick="logBookCourse()">Log here</button></div>`}
function yardageBook(){const records=bookRecords(),courses=bookCourses(records),years=seasonYears(),s=seasonSummary(records,state.profile.goal,bookYear),mapped=courses.filter(c=>c.location).length;if(bookSelected>=courses.length)bookSelected=0;return `<div class="yardage-book"><div class="book-heading"><div><span class="eyebrow">Every round takes you somewhere</span><h1>Your Yardage Book</h1><p class="muted">A golf life, one fairway at a time.</p></div><label class="book-year">Show<select onchange="setBookYear(this.value)">${years.map(y=>`<option ${bookYear===y?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="book-totals"><span><strong>${records.length}</strong> rounds</span><span><strong>${courses.length}</strong> courses</span><span><strong>${records.reduce((n,r)=>n+r.holes,0)}</strong> holes</span></div><div class="book-segments" role="group" aria-label="Yardage Book views">${[['stats','Your year'],['map','Places'],['memories','Memories']].map(([key,label])=>`<button class="${bookSection===key?'selected':''}" aria-pressed="${bookSection===key}" onclick="selectBookSection('${key}')">${label}</button>`).join('')}</div>${bookSection==='map'?`<div class="book-explore"><section class="book-map-wrap"><div id="journey-map" role="region" aria-label="Map of courses you have played"><div class="map-message">${mapped?'Opening your golf map…':'Your map starts with a place.'}<p>${mapped?'':'Choose a course below to place it, or find a course when logging your next round.'}</p></div></div><div class="map-caption"><span>${mapped} of ${courses.length} courses mapped</span><button class="text small" onclick="fitBookMap()">Show all places</button></div></section><section class="book-detail" id="book-detail">${bookCourseDetail()}</section></div><div class="book-course-list">${courses.map((c,i)=>`<button class="${i===bookSelected?'selected':''}" onclick="selectBookCourse(${i})" aria-pressed="${i===bookSelected}"><span class="place-number">${i+1}</span><span><strong>${esc(c.name)}</strong><small>${c.rounds.length} rounds · ${c.location?'On your map':'Place on map'}</small></span>${golfMark('arrow')}</button>`).join('')}</div>${!courses.length?'<button onclick="roundForm()">Log your first round</button>':''}`:bookSection==='highlights'?`<section class="book-highlights"><div class="section-title"><div><h2>Look how far you’ve come.</h2><p class="muted">${bookYear||'All-time'} highlights from your own rounds.</p></div><button class="secondary" onclick="showSeasonCard()">Share this year’s card</button></div><div class="book-personal-best"><span>BEST 18-HOLE ROUND</span><strong>${s.best??'—'}</strong><p>${s.best===null?'Your next round could be the one.':'A score to smile about.'}</p></div><div class="milestone-grid">${earnedMilestones(s).map(m=>`<div class="milestone ${m.earned?'is-earned':''}"><span class="milestone-medal">${golfMark(m.kind)}</span><strong>${m.name}</strong><small>${m.earned?'Earned':m.id==='goal'?'Reach '+s.goal+' rounds':m.detail.replace(' this year','')}</small></div>`).join('')}</div><section class="book-trend"><h2>Your scoring story</h2>${trend(records)}<p class="feature-caption">Unofficial handicap estimate · 18-hole rounds</p></section></section>`:`<section class="book-memories"><div class="section-title"><h2>The moments between shots.</h2><button onclick="noteForm()">Add a memory</button></div>${state.notes.filter(n=>!bookYear||n.date.startsWith(bookYear)).map(n=>`<button class="memory-entry" onclick="noteForm('${n.id}')"><small>${esc(n.date)}</small><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></button>`).join('')||'<p class="muted">A perfect shot. A terrible bounce. A great day out. Keep it here.</p>'}<div class="book-photo-wall">${records.flatMap(r=>(r.photos||[]).map(p=>`<figure><img src="${p}" alt="Round at ${esc(r.course)}"><figcaption>${esc(r.course)} · ${esc(r.date)}</figcaption></figure>`)).join('')}</div></section>`}</div>`}
function bookRoundHistory(){const c=bookCourses(bookRecords())[bookSelected];if(c){trackingFilters={query:c.name,year:activeBookYear()||'all',holes:'all',sort:'newest'};go('Rounds')}}
function logBookCourse(){const c=bookCourses(bookRecords())[bookSelected];if(c){roundForm();fillRoundCourse({...c.rounds[0],name:c.name,saved:true,location:c.location})}}
function placeBookCourse(){const c=bookCourses(bookRecords())[bookSelected];if(!c)return;clubSearch();bookLink={name:c.name,owner:state};document.querySelector('#club-query').value=c.name;searchClubs()}
const journeyChooseClub=chooseClub;chooseClub=function(i){if(!bookLink)return journeyChooseClub(i);const c=courseResults[i],location=courseLocation(c),target=bookLink;if(!location){toast('Choose a result with a course location.');return}if(target.owner!==state){modal.close();return}const previous=state.rounds;state.rounds=previous.map(r=>r.course.trim().toLowerCase()===target.name.trim().toLowerCase()?{...r,location}:r);if(persist()===false){state.rounds=previous;return}modal.close();render();toast('Course placed in your Yardage Book.')};
modal.addEventListener('close',()=>{bookLink=null});
function loadBookMap(){if(window.L)return Promise.resolve(window.L);if(bookLoader)return bookLoader;bookLoader=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';css.integrity='sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=';css.crossOrigin='anonymous';document.head.append(css);const js=document.createElement('script');js.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';js.integrity='sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=';js.crossOrigin='anonymous';js.onload=()=>resolve(window.L);js.onerror=()=>{js.remove();css.remove();bookLoader=null;reject(Error('map unavailable'))};document.head.append(js)});return bookLoader}
function fitBookMap(){if(!bookMap)return;const points=bookCourses(bookRecords()).filter(c=>c.location).map(c=>[c.location.lat,c.location.lon]);if(points.length)bookMap.fitBounds(points,{padding:[40,40],maxZoom:13,animate:!matchMedia('(prefers-reduced-motion: reduce)').matches})}
function selectBookCourse(i){bookSelected=i;const c=bookCourses(bookRecords())[i],detail=document.querySelector('#book-detail');if(detail)detail.innerHTML=bookCourseDetail();document.querySelectorAll('.book-course-list>button').forEach((b,n)=>{b.classList.toggle('selected',n===i);b.setAttribute('aria-pressed',String(n===i))});if(c?.location&&bookMap)bookMap.flyTo([c.location.lat,c.location.lon],12,{animate:!matchMedia('(prefers-reduced-motion: reduce)').matches,duration:.65})}
async function mountBookMap(epoch){const points=bookCourses(bookRecords()).filter(c=>c.location),element=document.querySelector('#journey-map');if(!element||!points.length)return;try{const L=await loadBookMap();if(epoch!==bookEpoch||!element.isConnected||tab!=='Passport')return;element.innerHTML='';bookMap=L.map(element,{scrollWheelZoom:false});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(bookMap);bookCourses(bookRecords()).forEach((c,i)=>{if(c.location){const marker=L.marker([c.location.lat,c.location.lon],{title:c.name,icon:L.divIcon({className:'book-map-pin',html:`<span>${i+1}</span>`,iconSize:[36,36],iconAnchor:[18,36]})}).addTo(bookMap).on('click',()=>selectBookCourse(i));marker.getElement()?.setAttribute('aria-label','Show '+c.name)}});fitBookMap()}catch(e){if(epoch===bookEpoch&&element.isConnected)element.innerHTML='<div class="map-message">The map couldn’t load.<p>Your course list and rounds are still here. Try again when you’re online.</p><button onclick="render()">Try map again</button></div>'}}
views.Home=focusedHome;views.Passport=yardageBook;
const journeyRender=render;render=function(){bookEpoch++;if(bookMap){bookMap.remove();bookMap=null}journeyRender();if(tab==='Passport'&&bookSection==='map')mountBookMap(bookEpoch)};
const journeyGo=go;go=function(t){journeyGo(t);if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&main.animate)main.animate([{opacity:.45,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.7,.2,1)'})};

// Shared by the browser, import checks and the Supabase course-data function.
function normalizeCourse(raw){
 const text=(v,n=100)=>typeof v==='string'?v.slice(0,n):'',num=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max?v:null;
 const id=text(raw.id),name=text(raw.course_name||raw.name);if(!/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/i.test(id)||!name)throw Error('Invalid course');
 const holes=Array.isArray(raw.holes_data)?raw.holes_data:[];
 const tees=(Array.isArray(raw.tees)?raw.tees:[]).slice(0,40).map((t,i)=>{const key=text(t.tee_color||t.tee_name).toLowerCase(),gender=text(t.gender,20);return {id:text(t.tee_key||String(i)),name:text(t.tee_name,40),gender,rating:num(t.course_rating,20,90),slope:num(t.slope,55,155),yardage:num(t.yardage,100,15000),par:num(t.par,18,100),holes:holes.slice(0,18).map(h=>({number:num(h.number,1,18),par:num(h.par,3,7),handicap:num(h.handicap_index,1,18),yards:num(h.yardages?.[key],30,1500)})).filter(h=>Number.isInteger(h.number))}}).filter(t=>t.name);
 const lat=num(raw.lat??raw.latitude,-90,90),lon=num(raw.lng??raw.longitude,-180,180),address=text(raw.address||[raw.city,raw.state].filter(Boolean).join(', '),500);
 return {id,name,holes:[9,18].includes(raw.holes)?raw.holes:null,location:lat!==null&&lon!==null?{lat,lon,address}:null,address,tees,source:'OpenGolfAPI',attribution:'© OpenStreetMap contributors (ODbL 1.0) via OpenGolfAPI'};
}
function validCourseCard(card){
 if(!card||!(card.courseHoles===undefined||card.courseHoles===null||[9,18].includes(card.courseHoles))||card.source!=='OpenGolfAPI'||typeof card.courseId!=='string'||!/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/i.test(card.courseId)||!card.tee)return false;
 const t=card.tee,str=(v,n)=>typeof v==='string'&&v.length<=n,num=(v,a,b)=>v===null||typeof v==='number'&&Number.isFinite(v)&&v>=a&&v<=b;
 return str(t.id,100)&&str(t.name,40)&&str(t.gender,20)&&num(t.rating,20,90)&&num(t.slope,55,155)&&num(t.yardage,100,15000)&&num(t.par,18,100)&&Array.isArray(t.holes)&&t.holes.length<=18&&new Set(t.holes.map(h=>h.number)).size===t.holes.length&&t.holes.every(h=>Number.isInteger(h.number)&&h.number>=1&&h.number<=18&&num(h.par,3,7)&&num(h.handicap,1,18)&&num(h.yards,30,1500));
}

// Licensed course facts are separate from account-owned golf records.
const COURSE_CREDIT='© OpenStreetMap contributors (ODbL 1.0) via OpenGolfAPI';
let importedCourse=null,selectedCourseCard=null,courseEntryEpoch=0,courseNine='front';
const courseMemory=new Map(),courseSearchMemory=new Map();
function validImportedCourse(c){return c&&c.source==='OpenGolfAPI'&&typeof c.name==='string'&&c.name.length<=100&&Array.isArray(c.tees)&&c.tees.length<=40&&c.tees.every(t=>validCourseCard({source:c.source,courseId:c.id,tee:t}))}
function rememberCourse(c){c={...c,cachedAt:c.cachedAt||new Date().toISOString()};if(!validImportedCourse(c))throw Error('Invalid course card');courseMemory.delete(c.id);courseMemory.set(c.id,c);while(courseMemory.size>20)courseMemory.delete(courseMemory.keys().next().value);try{localStorage.setItem('dogleg-course-cache-v1',JSON.stringify([...courseMemory.values()]))}catch{}return c}
try{const cached=JSON.parse(localStorage.getItem('dogleg-course-cache-v1')||'[]');if(Array.isArray(cached))for(const c of cached.slice(-20))if(validImportedCourse(c))courseMemory.set(c.id,c)}catch{}
async function courseRequest(params){
 const id=params.id;let stale=id?courseMemory.get(id):null;if(stale&&Date.now()-Date.parse(stale.cachedAt)<30*86400000)return stale;
 const query=new URLSearchParams(params),rest=new URLSearchParams({select:'data,fetched_at',...(id?{id:'eq.'+id}:{name:'ilike.*'+params.q.replace(/[\\%_*]/g,'\\$&')+'*',limit:'12'})});let cached=[];
 try{const response=await fetch(CLOUD_URL+'/rest/v1/dogleg_course_catalog?'+rest,{headers:{apikey:CLOUD_KEY},signal:AbortSignal.timeout(5000)});if(response.ok){const rows=await response.json();cached=rows.map(r=>({...r.data,cachedAt:r.fetched_at})).filter(validImportedCourse);if(id&&cached[0]){stale=cached[0];if(Date.now()-Date.parse(stale.cachedAt)<30*86400000)return rememberCourse(stale)}}}catch{}
 try{let result;if(cloudUser){const client=await cloudInit(),{data}=await client.auth.getSession();const response=await fetch(CLOUD_URL+'/functions/v1/course-data?'+query,{headers:{apikey:CLOUD_KEY,Authorization:'Bearer '+(data.session?.access_token||'')},signal:AbortSignal.timeout(18000)});if(!response.ok)throw Error();result=await response.json()}else{const response=await fetch('https://api.opengolfapi.org'+(id?'/api/v1/courses/'+encodeURIComponent(id):'/v1/courses/search?q='+encodeURIComponent(params.q)),{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error();const raw=await response.json();result=id?normalizeCourse(raw):{courses:(raw.courses||[]).flatMap(c=>{try{return [normalizeCourse(c)]}catch{return []}})}}
 if(id)return rememberCourse(result);if(!cached.length&&!result.courses?.length&&/^(the|le|les)\s+/i.test(params.q))return courseRequest({q:params.q.replace(/^(the|le|les)\s+/i,'')});return [...cached,...(result.courses||[]).filter(c=>!cached.some(r=>r.id===c.id))].slice(0,12);
 }catch(e){if(id&&stale)return rememberCourse(stale);if(!id&&cached.length)return cached;throw Error('Course scorecards are unavailable. You can still enter your round manually.')}
}
function sameCourseChoice(a,b){if(a===b)return true;if(a.courseId&&b.courseId)return a.courseId===b.courseId;if(a.name.trim().toLowerCase()!==b.name.trim().toLowerCase())return false;const x=a.location||a,y=b.location||b;return Number.isFinite(x.lat)&&Number.isFinite(y.lat)&&Math.abs(x.lat-y.lat)<0.02&&Math.abs(x.lon-y.lon)<0.02}
function courseChoice(c){return {name:c.name,address:c.address,holes:String(c.holes||''),location:c.location,courseId:c.id,source:c.source}}
function preferredCourseTee(course,previous){const tees=course.tees||[];if(previous?.courseCard&&previous.courseCard.courseId===course.id){const exact=tees.findIndex(t=>t.id===previous.courseCard.tee.id);if(exact>=0)return exact}const matches=tees.map((t,i)=>({t,i})).filter(({t})=>t.name.trim().toLowerCase()===String(previous?.tees||'').trim().toLowerCase());if(matches.length===1)return matches[0].i;const standard=tees.findIndex(t=>t.name.trim().toLowerCase()==='white'&&Number.isFinite(t.rating)&&Number.isFinite(t.slope));if(standard>=0)return standard;const complete=tees.findIndex(t=>Number.isFinite(t.rating)&&Number.isFinite(t.slope));return complete>=0?complete:tees.length?0:-1}
const basicFindRoundCourses=findRoundCourses;findRoundCourses=async function(name,token){const directory=basicFindRoundCourses(name,token);try{let courses=courseSearchMemory.get(name.toLowerCase());if(!courses){courses=await courseRequest({q:name});courseSearchMemory.set(name.toLowerCase(),courses)}const form=document.querySelector('#round-form'),input=form?.querySelector('[name=course]');if(token!==roundCourseRequest||!input||input.value.trim()!==name)return;if(!courses.length)return directory;const imported=courses.map(courseChoice),saved=savedCourseMatches(state.rounds,name);const others=roundCourseResults.filter(c=>!c.courseId&&!c.saved);renderRoundCourses([...imported,...saved,...others].filter((c,i,all)=>all.findIndex(x=>sameCourseChoice(x,c))===i).slice(0,12));document.querySelector('#round-course-status').textContent='Choose a course. Tee details are optional; course name, date, and score are enough.'}catch{if(token===roundCourseRequest)return directory}};
const directorySearchClubs=searchClubs;searchClubs=async function(position){
 if(position)return directorySearchClubs(position);
 const name=document.querySelector('#club-query')?.value.trim();
 if(!name||name.length<3)return clubStatus('Enter at least 3 letters of the course name.');
 if(clubBusy)return;
 courseResults=[];
 const directory=directorySearchClubs(),token=clubRequestId;
 try{
  const courses=await courseRequest({q:name});
  if(token!==clubRequestId||!document.querySelector('#club-results'))return;
  if(!courses.length)return directory;
  const imported=courses.map(courseChoice);
  courseResults=[...imported,...courseResults.filter(c=>!imported.some(s=>sameCourseChoice(s,c)))].slice(0,35);
  document.querySelector('#club-results').innerHTML=courseResults.map((c,i)=>`<div class="row"><div class="grow"><strong><span class="course-inline-badge">${courseBadge(c)}</span>${esc(c.name)}</strong><small>${esc(c.address||'Location shown on course page')} · ${c.courseId?'Select to check tee sets':'Directory listing'}</small></div><div class="hub-search-actions"><button class="secondary small" onclick="openSearchCourse(${i})">View course</button><button class="small" onclick="chooseClub(${i})">Log a round</button></div></div>`).join('');
  clubStatus('Choose a course. Published scorecard coverage varies. '+COURSE_CREDIT);clubBusy=false;document.querySelectorAll('#modal .toolbar button').forEach(b=>b.disabled=false);
 }catch{return directory}
};
const baseFillRoundCourse=fillRoundCourse;fillRoundCourse=function(c){courseEntryEpoch++;const epoch=courseEntryEpoch;baseFillRoundCourse(c);importedCourse=null;selectedCourseCard=null;const saved=state.rounds.find(r=>!r.sample&&r.course.trim().toLowerCase()===c.name.trim().toLowerCase()&&validCourseCard(r.courseCard));let snapshot=validCourseCard(c.courseCard)?c.courseCard:(c.courseId||c.saved?saved?.courseCard:null);if(c.courseId&&snapshot?.courseId!==c.courseId)snapshot=null;if(snapshot)selectedCourseCard=JSON.parse(JSON.stringify(snapshot));renderCourseControls();const previous=c.saved?c:[...state.rounds].filter(r=>!r.sample&&r.course.trim().toLowerCase()===c.name.trim().toLowerCase()).sort((a,b)=>b.date.localeCompare(a.date))[0];const id=c.courseId||snapshot?.courseId;if(!id)return;if(!snapshot){const activeForm=document.querySelector('#round-form');for(const field of ['tees','rating','slope'])activeForm.querySelector('[name='+field+']').value=''}const form=document.querySelector('#round-form'),journal=state;const status=document.querySelector('#round-course-status');status.textContent='Opening tee sets and scorecard…';courseRequest({id}).then(course=>{if(epoch!==courseEntryEpoch||state!==journal||!form?.isConnected||document.querySelector('#round-form')!==form||form.querySelector('[name=course]').value.trim().toLowerCase()!==c.name.trim().toLowerCase())return;importedCourse=course;roundCourseLocation=course.location;roundLocationName=c.name.trim().toLowerCase();renderCourseControls();if(snapshot){const index=course.tees.findIndex(t=>t.id===snapshot.tee.id);if(index>=0)document.querySelector('#course-tee-select').value=String(index)}if(!snapshot&&course.tees.length&&!form.querySelector('[name=rating]').value&&!form.querySelector('[name=slope]').value){const index=preferredCourseTee(course,previous);if(index>=0)selectCourseTee(String(index))}if(snapshot)status.textContent='Your previous tee card is ready. Change the tee set if you played different tees.';else if(!selectedCourseCard)status.textContent=course.tees.length?'Choose your tee set to fill rating and slope.':'No tee card is available from our provider. You can save without tee details.'}).catch(e=>{if(epoch===courseEntryEpoch&&form?.isConnected)status.textContent=e.message})};
function courseIsEighteen(card=selectedCourseCard){return card?.courseHoles===18||!!card?.tee.holes.some(h=>h.number>9)}
function courseCardHoles(){if(!selectedCourseCard)return [];const holes=selectedCourseCard.tee.holes,n=+document.querySelector('#round-form [name=holes]')?.value;if(n===9&&courseIsEighteen())return holes.filter(h=>courseNine==='back'?h.number>9:h.number<=9);return holes}
function renderCourseControls(){const root=document.querySelector('#course-card-controls');if(!root)return;root.innerHTML=`${importedCourse?.tees.length?`<label>Tee set<select id="course-tee-select" onchange="selectCourseTee(this.value)"><option value="">Choose the tees you played</option>${importedCourse.tees.map((t,i)=>`<option value="${i}" ${selectedCourseCard?.tee.id===t.id?'selected':''}>${esc(t.name)} · ${esc(t.gender)}${t.yardage!==null?' · '+t.yardage+' yd':''}${t.rating!==null?' · '+t.rating+'/'+(t.slope??'—'):''}</option>`).join('')}</select></label>`:''}${selectedCourseCard?`<div class="imported-scorecard"><p><strong>${+document.querySelector('#round-form [name=holes]').value===9&&courseIsEighteen()?'Full 18-hole tee card: ':''}${esc(selectedCourseCard.tee.name)} · ${esc(selectedCourseCard.tee.gender)}</strong> · ${selectedCourseCard.tee.yardage??'—'} yd · Par ${selectedCourseCard.tee.par??'—'} <button type="button" class="text small" onclick="clearCourseCard()">Use manual details</button></p>${+document.querySelector('#round-form [name=holes]').value===9&&courseIsEighteen()?'<label>Nine played<select onchange="courseNine=this.value;renderCourseControls();drawHoles(9)"><option value="front" '+(courseNine==='front'?'selected':'')+'>Front nine</option><option value="back" '+(courseNine==='back'?'selected':'')+'>Back nine</option></select></label><p class="feature-caption">Enter the rating and slope for this nine from your scorecard; the 18-hole rating does not apply.</p>':''}<details><summary>Course scorecard</summary><div class="course-card-table"><table><thead><tr><th>Hole</th><th>Yards</th><th>Par</th><th>HCP</th></tr></thead><tbody>${courseCardHoles().map(h=>`<tr><th>${h.number}</th><td>${h.yards??'—'}</td><td>${h.par??'—'}</td><td>${h.handicap??'—'}</td></tr>`).join('')}</tbody></table></div></details><p class="feature-caption">Missing values are shown as —. Check the current club scorecard if anything differs.</p></div>`:''}${importedCourse||selectedCourseCard?`<p class="feature-caption"><a href="https://opengolfapi.org/attribution/" target="_blank" rel="noopener">${COURSE_CREDIT}</a></p>`:''}`}
function selectCourseTee(value){if(value==='')return clearCourseCard();const t=importedCourse?.tees[Number(value)];if(!t)return;selectedCourseCard={source:'OpenGolfAPI',courseId:importedCourse.id,courseHoles:importedCourse.holes,attribution:COURSE_CREDIT,license:'ODbL-1.0',tee:JSON.parse(JSON.stringify(t))};const form=document.querySelector('#round-form');form.querySelector('[name=tees]').value=t.name;const nine=+form.querySelector('[name=holes]').value===9&&courseIsEighteen();form.querySelector('[name=rating]').value=nine?'':t.rating??'';form.querySelector('[name=slope]').value=nine?'':t.slope??'';renderCourseControls();drawHoles(form.querySelector('[name=holes]').value);const status=document.querySelector('#round-course-status');if(status)status.textContent=nine?'Choose the front or back nine; enter its published nine-hole rating and slope.':(t.rating!==null&&t.slope!==null?'Rating and slope filled automatically for ':'Published rating or slope is missing for ')+t.name+' · '+t.gender+'. Change the tee set if needed.'}
function matchCourseTee(name){if(!importedCourse)return clearCourseCard();const gender=selectedCourseCard?.tee.gender,matches=importedCourse.tees.map((t,i)=>({t,i})).filter(({t})=>t.name.trim().toLowerCase()===name.trim().toLowerCase()),same=matches.filter(({t})=>t.gender===gender),match=matches.length===1?matches[0]:same.length===1?same[0]:null;if(match)return selectCourseTee(String(match.i));clearCourseCard();const form=document.querySelector('#round-form');for(const field of ['rating','slope'])form.querySelector('[name='+field+']').value='';const status=document.querySelector('#round-course-status');if(status)status.textContent='Choose a tee set above to load its rating and slope, or enter manual details.'}
function clearCourseCard(){selectedCourseCard=null;renderCourseControls();const form=document.querySelector('#round-form');if(form)drawHoles(form.querySelector('[name=holes]').value)}
function courseRoundLength(value){if(selectedCourseCard){const nine=+value===9&&courseIsEighteen(),form=document.querySelector('#round-form');form.querySelector('[name=rating]').value=nine?'':selectedCourseCard.tee.rating??'';form.querySelector('[name=slope]').value=nine?'':selectedCourseCard.tee.slope??'';renderCourseControls()}drawHoles(value)}
const courseRoundForm=roundForm;roundForm=function(id){courseEntryEpoch++;importedCourse=null;selectedCourseCard=null;courseNine='front';courseRoundForm(id);const r=id?state.rounds.find(r=>r.id===id):state.draft;if(validCourseCard(r?.courseCard)){selectedCourseCard=JSON.parse(JSON.stringify(r.courseCard));courseNine=r.courseNine==='back'?'back':'front';renderCourseControls();drawHoles(r.holes,r.scores);const epoch=courseEntryEpoch,form=document.querySelector('#round-form'),journal=state;courseRequest({id:r.courseCard.courseId}).then(c=>{if(epoch!==courseEntryEpoch||journal!==state||!form?.isConnected)return;importedCourse=c;renderCourseControls()}).catch(()=>{})}};
const courseReadRound=readRound;readRound=function(){const round=courseReadRound();if(validCourseCard(selectedCourseCard)&&round.course.trim().toLowerCase()===roundLocationName&&round.tees===selectedCourseCard.tee.name)round.courseCard=JSON.parse(JSON.stringify(selectedCourseCard)),round.courseNine=courseNine;return round};
const courseDrawHoles=drawHoles;drawHoles=function(n,values){courseDrawHoles(n,values);const holes=courseCardHoles();document.querySelectorAll('#holes label').forEach((label,i)=>{const h=holes[i];if(!h)return;label.childNodes[0].textContent='Hole '+h.number;const info=document.createElement('small');info.className='hole-course-facts';info.textContent=(h.yards??'—')+' yd · Par '+(h.par??'—')+' · HCP '+(h.handicap??'—');label.append(info)})};
const courseQueue=queueRoundCourses;queueRoundCourses=function(value){courseEntryEpoch++;if(value.trim().toLowerCase()!==roundLocationName){const form=document.querySelector('#round-form');if(form)for(const field of ['tees','rating','slope'])form.querySelector('[name='+field+']').value='';importedCourse=null;selectedCourseCard=null;renderCourseControls()}courseQueue(value)};
modal.addEventListener('close',()=>{courseEntryEpoch++;importedCourse=null;selectedCourseCard=null});

// Annual recaps use recorded data only. Unknown is different from zero.
let seasonSpotlight=0;
function validRoundExtras(e){return !!e&&typeof e==='object'&&!Array.isArray(e)&&['outOfBounds','waterBalls','penaltyStrokes','minutes'].every(k=>e[k]===undefined||e[k]===null||Number.isInteger(e[k])&&e[k]>=0&&e[k]<=(k==='minutes'?1440:99))}
function roundExtrasEditor(r){return `<details class="round-extra"><summary>A little more about your round (optional)</summary><p class="feature-caption">Leave a field blank if you didn’t track it. Enter 0 for none. Penalty strokes should already be included in your total score.</p><div class="form-grid">${[['outOfBounds','Balls out of bounds'],['waterBalls','Balls into water'],['penaltyStrokes','Penalty strokes'],['minutes','Time played (minutes)']].map(([key,label])=>`<label>${label}<input name="extra-${key}" type="number" min="0" max="${key==='minutes'?1440:99}" step="1" value="${r.extras?.[key]??''}" placeholder="Not tracked"></label>`).join('')}</div></details>`}
function seasonRoundHoles(r){if(!r.courseCard||!validCourseCard(r.courseCard))return [];let holes=[...r.courseCard.tee.holes].sort((a,b)=>a.number-b.number);if(r.holes===9&&(r.courseCard.courseHoles===18||holes.some(h=>h.number>9)))holes=holes.filter(h=>r.courseNine==='back'?h.number>9:h.number<=9);return holes.slice(0,r.holes).map(h=>{const index=r.holes===9?h.number-(r.courseNine==='back'?10:1):h.number-1;return {...h,round:r,score:!r.scoreNotKept&&Number.isInteger(r.scores?.[index])?r.scores[index]:null}})}
function annualStats(records,year){
 const rounds=records.filter(r=>!r.sample&&r.date.slice(0,4)===String(year)),best=n=>[...rounds].filter(r=>r.holes===n&&Number.isFinite(r.score)).sort((a,b)=>a.score-b.score||a.date.localeCompare(b.date))[0]||null;
 const holes=rounds.flatMap(seasonRoundHoles),measured=holes.filter(h=>Number.isFinite(h.yards)),scored=holes.filter(h=>Number.isFinite(h.par)&&Number.isInteger(h.score)),buckets={eagle:[],birdie:[],par:[],bogey:[],double:[]};
 for(const h of scored){const d=h.score-h.par;buckets[d<=-2?'eagle':d===-1?'birdie':d===0?'par':d===1?'bogey':'double'].push(h)}
 const reported=key=>{const known=rounds.filter(r=>validRoundExtras(r.extras)&&Number.isInteger(r.extras[key]));return {total:known.length?known.reduce((n,r)=>n+r.extras[key],0):null,known:known.length,rounds:known}};
 let streak=null;for(const r of rounds){let run=[];for(const h of seasonRoundHoles(r)){if(h.score!==null&&h.par!==null&&h.score<=h.par&&(!run.length||h.number===run.at(-1).number+1))run.push(h);else run=h.score!==null&&h.par!==null&&h.score<=h.par?[h]:[];if(run.length>(streak?.length||0))streak={length:run.length,first:run[0],last:h}}}
 const average=n=>{const eligible=rounds.filter(r=>r.holes===n&&Number.isFinite(r.score));return eligible.length?Math.round(eligible.reduce((sum,r)=>sum+r.score,0)/eligible.length*10)/10:null};
 const puttRounds=rounds.filter(r=>Number.isInteger(r.putts)),courses=bookCourses(rounds).sort((a,b)=>b.rounds.length-a.rounds.length||a.name.localeCompare(b.name));
 return {rounds,average18:average(18),average9:average(9),strokes:rounds.reduce((n,r)=>n+(r.score??0),0),holesPlayed:rounds.reduce((n,r)=>n+r.holes,0),best18:best(18),best9:best(9),holes,measured,scored,buckets,streak,longest:[...measured].sort((a,b)=>b.yards-a.yards)[0]||null,shortest:[...measured].sort((a,b)=>a.yards-b.yards)[0]||null,putts:{total:puttRounds.length?puttRounds.reduce((n,r)=>n+r.putts,0):null,known:puttRounds.length,rounds:puttRounds},outOfBounds:reported('outOfBounds'),waterBalls:reported('waterBalls'),penaltyStrokes:reported('penaltyStrokes'),minutes:reported('minutes'),days:new Set(rounds.map(r=>r.date)).size,courses,months:Array.from({length:12},(_,i)=>rounds.filter(r=>+r.date.slice(5,7)===i+1))};
}
function seasonYears(){return [...new Set([String(new Date().getFullYear()),...state.rounds.filter(r=>!r.sample).map(r=>r.date.slice(0,4)),...state.notes.map(n=>n.date.slice(0,4))])].sort().reverse()}
function seasonHeader(section){return `<div class="book-heading"><div><span class="eyebrow">The score is only half the story</span><h1>Your ${esc(bookYear)} Yardage Book</h1><p class="muted">Big swings. Small victories. Your year in golf.</p></div><label class="book-year">Season<select onchange="setBookYear(this.value)">${seasonYears().map(y=>`<option ${bookYear===y?'selected':''}>${y}</option>`).join('')}</select></label></div><div class="book-segments" role="group" aria-label="Yardage Book views">${[['stats','Your year'],['map','Places'],['memories','Memories']].map(([key,label])=>`<button class="${section===key?'selected':''}" aria-pressed="${section===key}" onclick="selectBookSection('${key}')">${label}</button>`).join('')}</div>`}
function seasonRef(r,h){return `${esc(r.course)}${h?' · Hole '+h.number:''}<br>${esc(r.tees)} tees · ${esc(r.date)}`}
function seasonHighlights(s){const options=[];for(const [key,r,length] of [['best18',s.best18,18],['best9',s.best9,9]])if(r)options.push({key,label:'Your best '+length+'-hole round',value:r.score,unit:'strokes',ref:seasonRef(r),copy:'One for the memory bank.'});for(const [key,h,label] of [['longest',s.longest,'The long way home'],['shortest',s.shortest,'Small hole. Big memories.']])if(h)options.push({key,label,value:h.yards,unit:'yard '+(key==='longest'?'longest':'shortest')+' recorded hole',ref:seasonRef(h.round,h),copy:'From the tee card saved with your round.'});if(s.streak)options.push({key:'streak',label:'You found your rhythm',value:s.streak.length,unit:'consecutive holes at par or better',ref:seasonRef(s.streak.first.round)+'<br>Holes '+s.streak.first.number+'–'+s.streak.last.number,copy:'Your best run within a single round.'});if(!options.length)options.push({key:'strokes',label:'Your story starts on the first tee',value:s.strokes,unit:'strokes recorded',ref:'Log a round to start collecting your highlights.',copy:'Every round adds a new chapter.'});return options}
function seasonSpotlightHtml(s){const options=seasonHighlights(s),item=options[seasonSpotlight%options.length];return `<span class="eyebrow">${item.label}</span><button class="spotlight-number" onclick="seasonDetail('${item.key}')"><strong>${item.value.toLocaleString()}</strong><span>${item.unit}</span></button><p class="spotlight-ref">${item.ref}</p><div class="spotlight-bottom"><small>${item.copy}</small><button class="text" onclick="nextSeasonHighlight()">Another highlight ${golfMark('arrow')}</button></div>`}
function nextSeasonHighlight(){seasonSpotlight++;const el=document.querySelector('#season-spotlight');if(el){el.innerHTML=seasonSpotlightHtml(annualStats(state.rounds,bookYear));if(!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate?.([{opacity:.35,transform:'translateX(10px)'},{opacity:1,transform:'translateX(0)'}],{duration:220})}}
function seasonMetric(key,value,label,caption=''){return `<button class="season-metric" onclick="seasonDetail('${key}')"><strong>${value===null?'—':value.toLocaleString()}</strong><span>${label}</span><small>${caption||'Tap to see the rounds'}</small></button>`}
function annualBook(){const s=annualStats(state.rounds,bookYear),coverage=v=>v.known+' of '+s.rounds.length+' rounds tracked',max=Math.max(1,...s.months.map(m=>m.length)),labels=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return `<div class="yardage-book annual-book">${seasonHeader('stats')}<section class="season-opening"><div><span class="eyebrow">Every swing counts</span><button class="season-stroke-total ${s.strokes>=10000?'is-large':''}" onclick="seasonDetail('strokes')"><strong>${s.strokes.toLocaleString()}</strong><span>total strokes in ${esc(bookYear)} ${golfMark('arrow')}</span></button><p class="season-opening-meta">${s.rounds.length} rounds · ${s.holesPlayed} holes · ${s.days} days on the course</p></div><button class="season-map-link" onclick="selectBookSection('map')">${golfMark('pin')}<strong>${s.courses.length}</strong><span>courses explored</span><small>Explore your places →</small></button></section><section class="season-spotlight" id="season-spotlight">${seasonSpotlightHtml(s)}</section><div class="season-section-heading"><div><h2>The ones you’ll talk about.</h2><p class="muted">Tap any record to revisit the round.</p></div></div><div class="season-records">${seasonMetric('average18',s.average18,'18-hole scoring average','Only 18-hole rounds')}${seasonMetric('average9',s.average9,'Nine-hole scoring average','Only nine-hole rounds')}${seasonMetric('best18',s.best18?.score??null,'Best 18-hole round',s.best18?esc(s.best18.course):'Your next round could be the one')}${seasonMetric('best9',s.best9?.score??null,'Best nine-hole round',s.best9?esc(s.best9.course):'Nine-hole rounds stay separate')}${seasonMetric('longest',s.longest?.yards??null,'Longest recorded hole',s.longest?esc(s.longest.round.course)+' · Hole '+s.longest.number:'Select a course + tees when logging')}${seasonMetric('shortest',s.shortest?.yards??null,'Shortest recorded hole',s.shortest?esc(s.shortest.round.course)+' · Hole '+s.shortest.number:'Saved tee yardages unlock this')}</div><p class="feature-caption">Hole records use ${s.measured.length} of ${s.holesPlayed} played holes with saved yardages. These are hole lengths, not shot distances. <a href="https://opengolfapi.org/attribution/" target="_blank" rel="noopener">© OpenStreetMap contributors via OpenGolfAPI</a>.</p><section class="season-activity"><h2>When golf happened.</h2><p class="muted">Tap a month to replay its rounds.</p><div class="season-months">${s.months.map((rounds,i)=>`<button onclick="seasonMonth(${i})" aria-label="${labels[i]} ${bookYear}: ${rounds.length} rounds"><span class="month-count">${rounds.length||''}</span><i style="height:${Math.max(4,rounds.length/max*92)}px"></i><small>${labels[i]}</small></button>`).join('')}</div></section><section class="season-score-story"><h2>A few reasons to come back.</h2><p class="muted">From ${s.scored.length} holes with both a saved par and a hole score.</p><div class="season-score-chips">${[['eagle','Eagle or better'],['birdie','Birdies'],['par','Pars'],['bogey','Bogeys'],['double','Double bogey+']].map(([key,label])=>`<button onclick="seasonDetail('${key}')"><strong>${s.scored.length?s.buckets[key].length:'—'}</strong><span>${label}</span></button>`).join('')}</div>${s.streak?`<button class="season-streak" onclick="seasonDetail('streak')">${golfMark('spark')}<span><strong>${s.streak.length} holes in a groove</strong><small>Your best in-round run at par or better →</small></span></button>`:'<p class="feature-caption">Hole-by-hole scores unlock your par-or-better streaks.</p>'}</section><section><h2>The whole story.</h2><p class="muted">The good, the wet, and the ones over the fence.</p><div class="season-records">${seasonMetric('putts',s.putts.total,'Putts recorded',coverage(s.putts))}${seasonMetric('outOfBounds',s.outOfBounds.total,'Balls out of bounds',coverage(s.outOfBounds))}${seasonMetric('waterBalls',s.waterBalls.total,'Balls into water',coverage(s.waterBalls))}${seasonMetric('penaltyStrokes',s.penaltyStrokes.total,'Penalty strokes',coverage(s.penaltyStrokes))}${seasonMetric('minutes',s.minutes.total===null?null:Math.round(s.minutes.total/60*10)/10,'Hours on the course',coverage(s.minutes))}${seasonMetric('favourite',s.courses[0]?.rounds.length??null,'Visits to your most-played course',s.courses[0]?esc(s.courses[0].name):'Your regular spot will appear here')}</div><p class="feature-caption">A dash means not tracked. Penalties are already part of total strokes and are not added again.</p></section><div class="season-finish"><p>${s.rounds.length?'Same game. A different story every round.':'Your year is waiting for its first story.'}</p><button onclick="roundForm()">Log a round</button><button class="text" onclick="seasonRecap()">Open my year recap</button></div></div>`}
function seasonRoundList(rounds){return rounds.map(r=>`<button class="season-receipt" onclick="roundForm('${r.id}')"><span><strong>${esc(r.course)}</strong><small>${esc(r.date)} · ${r.holes} holes · ${esc(r.tees)} tees</small></span><strong>${r.score??'Score not kept'}</strong>${golfMark('arrow')}</button>`).join('')||'<p class="muted">No rounds recorded for this stat yet.</p>'}
function seasonHoleList(holes){return holes.slice(0,60).map(h=>`<button class="season-receipt" onclick="roundForm('${h.round.id}')"><span><strong>${esc(h.round.course)} · Hole ${h.number}</strong><small>${esc(h.round.date)} · ${esc(h.round.tees)} tees · ${h.yards??'—'} yd · Par ${h.par??'—'}${h.score!==null?' · '+h.score+' strokes':''}</small></span>${golfMark('arrow')}</button>`).join('')+(holes.length>60?'<p class="feature-caption">Showing the first 60 of '+holes.length+' recorded holes.</p>':'')}
function seasonDetail(key){const s=annualStats(state.rounds,bookYear),titles={average18:'18-hole scoring average',average9:'Nine-hole scoring average',strokes:'Every swing counts',best18:'Best 18-hole round',best9:'Best nine-hole round',longest:'Longest recorded hole',shortest:'Shortest recorded hole',streak:'Your best in-round streak',putts:'Putts recorded',outOfBounds:'Balls out of bounds',waterBalls:'Balls into water',penaltyStrokes:'Penalty strokes',minutes:'Time on the course',favourite:'Your most-played course',eagle:'Eagle or better',birdie:'Birdies',par:'Pars',bogey:'Bogeys',double:'Double bogey or worse'};if(!titles[key])return;let body='';if(key==='average18'||key==='average9')body='<p>Average: '+(s[key]??'—')+' strokes. Round lengths are calculated separately.</p>'+seasonRoundList(s.rounds.filter(r=>r.holes===(key==='average18'?18:9)&&Number.isFinite(r.score)));else if(['longest','shortest'].includes(key))body=s[key]?seasonHoleList([s[key]]):'<p>Select a course and tees when logging to record hole yardages.</p>';else if(s.buckets[key])body=s.buckets[key].length?seasonHoleList(s.buckets[key]):'<p>No matching scored holes yet. Add hole scores and a course card to track this.</p>';else if(key==='streak')body=s.streak?`<p>${s.streak.length} consecutive holes at par or better. Holes ${s.streak.first.number}–${s.streak.last.number}.</p>`+seasonHoleList([s.streak.first]):'<p>Hole scores with saved pars unlock this record.</p>';else if(key==='best18'||key==='best9')body=seasonRoundList(s[key]?[s[key]]:[]);else if(key==='favourite')body=seasonRoundList(s.courses[0]?.rounds||[]);else if(key==='strokes')body=seasonRoundList(s.rounds);else{const m=s[key];body=`<p class="feature-caption">${m.known} of ${s.rounds.length} rounds tracked. Unknown rounds are excluded.</p>`+m.rounds.map(r=>`<button class="season-receipt" onclick="roundForm('${r.id}')"><span><strong>${esc(r.course)}</strong><small>${esc(r.date)}</small></span><strong>${key==='putts'?r.putts:r.extras[key]}${key==='minutes'?' min':''}</strong></button>`).join('');if(!m.known)body+='<p>Add this optional detail when logging or editing a round. Leave blank for unknown; enter 0 for none.</p>'+seasonRoundList(s.rounds.slice(-5))}openModal(titles[key]+' · '+esc(bookYear),body)}
function seasonMonth(index){const s=annualStats(state.rounds,bookYear),month=new Date(2000,index,1).toLocaleString('en',{month:'long'});openModal(esc(month)+' '+esc(bookYear),seasonRoundList(s.months[index]||[]))}
function seasonRecap(){const s=annualStats(state.rounds,bookYear);openModal('Your '+esc(bookYear)+' recap',`<div class="year-recap"><span class="eyebrow">DOGLEG · A life well played</span><h2>${esc(state.profile.name)}’s ${esc(bookYear)}</h2><strong>${s.strokes.toLocaleString()}</strong><p>strokes · ${s.rounds.length} rounds · ${s.courses.length} courses</p><p>Best 18: ${s.best18?.score??'—'} · Best nine: ${s.best9?.score??'—'}</p><p>Birdies: ${s.scored.length?s.buckets.birdie.length:'—'} from ${s.scored.length} scored holes with par.</p><p>OB balls recorded: ${s.outOfBounds.total??'—'} (${s.outOfBounds.known} rounds tracked)</p><small>Only recorded data for this season.</small></div><button class="section-gap" onclick="downloadYearRecap()">Download year recap</button><p id="year-recap-status" class="feature-caption" role="status"></p><img id="year-recap-preview" hidden alt="Your annual Dogleg recap" style="width:100%;height:auto;margin-top:16px;border-radius:16px">`)}
function downloadYearRecap(){try{const s=annualStats(state.rounds,bookYear),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');ctx.fillStyle='#174b3b';ctx.fillRect(0,0,1080,1350);ctx.fillStyle='#f6f7dd';const write=(text,x,y,size=28,weight=400)=>{ctx.font=weight+' '+size+'px "Source Sans 3",sans-serif';ctx.fillText(String(text),x,y,940)};write('DOGLEG  /  A LIFE WELL PLAYED',70,90,24,600);write(state.profile.name+'’s '+bookYear,70,175,52,600);write(s.strokes.toLocaleString(),65,385,s.strokes>=10000?135:170,700);write('TOTAL STROKES',75,440,25,600);write(s.rounds.length+' rounds  ·  '+s.courses.length+' courses  ·  '+s.holesPlayed+' holes',70,510,32);ctx.fillStyle='#9fc19a';ctx.fillRect(70,555,940,2);ctx.fillStyle='#f6f7dd';write('BEST 18',70,625,22,600);write(s.best18?.score??'—',70,705,64,700);write('BEST NINE',560,625,22,600);write(s.best9?.score??'—',560,705,64,700);write('BIRDIES',70,800,22,600);write(s.scored.length?s.buckets.birdie.length:'—',70,875,56,700);write('From '+s.scored.length+' holes with score + par',70,920,22);write('BALLS OUT OF BOUNDS',560,800,22,600);write(s.outOfBounds.total??'—',560,875,56,700);write(s.outOfBounds.known+' of '+s.rounds.length+' rounds tracked',560,920,22);write('LONGEST RECORDED HOLE',70,1015,22,600);write(s.longest?s.longest.yards+' yd  ·  Hole '+s.longest.number:'Not recorded yet',70,1070,35,600);if(s.longest){write(s.longest.round.course,70,1120,28);write(s.longest.round.tees+' tees  ·  '+s.longest.round.date,70,1160,24)}write('Only recorded season data. A dash means not tracked.',70,1240,21);write('Course data: OpenStreetMap contributors / OpenGolfAPI · ODbL 1.0',70,1280,19);const url=canvas.toDataURL('image/png'),preview=document.querySelector('#year-recap-preview');preview.src=url;preview.hidden=false;const link=document.createElement('a');link.href=url;link.download='dogleg-'+bookYear+'-recap.png';link.click();document.querySelector('#year-recap-status').textContent='Your recap is ready. Save the preview if your browser didn’t download it.'}catch{const status=document.querySelector('#year-recap-status');if(status)status.textContent='Could not create the image. You can still save a screenshot of your recap.'}}
const seasonBaseBook=views.Passport;views.Passport=()=>bookSection==='stats'?annualBook():seasonBaseBook();
const seasonReadRound=readRound;readRound=function(){const r=seasonReadRound(),form=document.querySelector('#round-form'),extras={};for(const key of ['outOfBounds','waterBalls','penaltyStrokes','minutes']){const value=form.querySelector('[name=extra-'+key+']')?.value;extras[key]=value===undefined||value===''?null:Number(value)}if(Object.values(extras).some(v=>v!==null))r.extras=extras;return r};

